/* ===== FOTO DE PERFIL (compartilhada — aparece para todos) =====
   Cada usuário guarda a sua em "mafra:perfil:<uid>". Cache em window._perfis.
   Avatares de todo o sistema usam _avStyle/_avInner: mostram a foto quando existe,
   senão a inicial sobre a cor da pessoa (padrão da marca). */
function _perfilFotoDe(uid){ return (window._perfis && window._perfis[uid]) ? window._perfis[uid] : ""; }
function _avStyle(uid, cor, extraCss){
  const f=_perfilFotoDe(uid);
  const base = f ? ("background-image:url('"+f+"');background-size:cover;background-position:center;background-repeat:no-repeat")
                 : ("background:"+(cor||"#16243D"));
  return base + (extraCss?(";"+extraCss):"");
}
function _avInner(uid, ini){ return _perfilFotoDe(uid) ? "" : ini; }
async function carregarPerfis(uids){
  window._perfis = window._perfis || {};
  try{
    const lista = (uids&&uids.length) ? uids : Object.keys(USUARIOS||{}).filter(u=>u!=="mafra");
    await Promise.all(lista.map(async function(uid){
      try{ const v=await storeGet("mafra:perfil:"+uid); if(v) window._perfis[uid]=v; else delete window._perfis[uid]; }catch(e){}
    }));
  }catch(e){}
  return window._perfis;
}
async function salvarPerfilFoto(uid, dataURL){
  const ok = await storeSet("mafra:perfil:"+uid, dataURL||"");
  if(ok){ window._perfis=window._perfis||{}; if(dataURL) window._perfis[uid]=dataURL; else delete window._perfis[uid]; }
  return ok;
}
function _pintarTopAvatar(){
  const el=document.getElementById("topAv"); if(!el || !state.user) return;
  const ini=(state.user.nome||"?").split(" ").map(w=>w[0]).slice(0,2).join("");
  el.setAttribute("style", _avStyle(state.userId, "linear-gradient(150deg,var(--navy),var(--navy2))"));
  el.innerHTML=_avInner(state.userId, ini);
}
function abrirFotoPerfil(){
  if(!state.user) return;
  const uid=state.userId;
  const ini=(state.user.nome||"?").split(" ").map(w=>w[0]).slice(0,2).join("");
  const tem=!!_perfilFotoDe(uid);
  const prevStyle="width:104px;height:104px;border-radius:50%;margin:0 auto;display:flex;align-items:center;justify-content:center;color:var(--gold);font-weight:800;font-size:34px;border:3px solid var(--line);"+_avStyle(uid,"linear-gradient(150deg,var(--navy),var(--navy2))");
  document.getElementById("modalMount").innerHTML=`<div class="overlay" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:380px">
    <div class="modal-head"><h3>${ico('camera')} Foto de perfil</h3><button class="x" onclick="closeModal()">×</button></div>
    <div class="modal-body" style="text-align:center">
      <div id="fpPrev" style="${prevStyle}">${_avInner(uid,ini)}</div>
      <p style="color:var(--muted);font-size:13px;margin:13px 0 16px;line-height:1.5">Sua foto aparece para toda a equipe no painel “Onde a Equipe Mafra está” e nos comentários.</p>
      <!-- build 135: sem capture="user" — no iPhone esse atributo força a câmera e esconde a galeria -->
      <input type="file" id="fpFile" accept="image/*" style="display:none" onchange="_fpEscolher(this)">
      <input type="file" id="fpCam" accept="image/*" capture="user" style="display:none" onchange="_fpEscolher(this)">
      <button class="btn-gold" style="width:100%" onclick="document.getElementById('fpFile').click()">${ico('imagem')} Escolher da galeria</button>
      <button class="btn-ghost" style="width:100%;margin-top:8px" onclick="document.getElementById('fpCam').click()">${ico('camera')} Tirar foto agora</button>
      ${tem?`<button class="btn-ghost" style="width:100%;margin-top:8px" onclick="_fpRemover()">🗑️ Remover foto atual</button>`:""}
      <div class="modal-foot" style="margin-top:18px">
        <button class="btn-cancel" onclick="closeModal()">Fechar</button>
        <button class="btn-gold" id="fpSalvar" style="flex:1;opacity:.5;pointer-events:none" onclick="_fpSalvar()">Salvar</button>
      </div>
    </div>
  </div></div>`;
}
let _fpNova=null;
async function _fpEscolher(input){
  const f=input.files&&input.files[0]; if(!f) return;
  try{ const _r=await comprimirImagem(f, 256, 0.72); _fpNova=(_r&&_r.foto)?_r.foto:_r; }catch(e){ alert("Não consegui ler a imagem. Tente outra foto."); return; }
  const prev=document.getElementById("fpPrev");
  if(prev){ prev.setAttribute("style","width:104px;height:104px;border-radius:50%;margin:0 auto;border:3px solid var(--line);background-image:url('"+_fpNova+"');background-size:cover;background-position:center"); prev.innerHTML=""; }
  const btn=document.getElementById("fpSalvar"); if(btn){ btn.style.opacity="1"; btn.style.pointerEvents="auto"; }
}
async function _fpSalvar(){
  if(!_fpNova){ closeModal(); return; }
  const ok=await salvarPerfilFoto(state.userId, _fpNova);
  if(!ok){ alert("Não consegui salvar a foto no servidor.\n\nVerifique a internet e tente de novo." + (window._lastStoreErr?("\n\nDetalhe técnico: "+window._lastStoreErr):"")); return; }
  _fpNova=null; closeModal(); _pintarTopAvatar();
  try{ render(); }catch(e){}
  try{ renderPainelLocalizacao(); }catch(e){}
  _toast("✅ Foto de perfil atualizada.");
}
async function _fpRemover(){
  if(!confirm("Remover sua foto de perfil?")) return;
  await salvarPerfilFoto(state.userId, "");
  _fpNova=null; closeModal(); _pintarTopAvatar();
  try{ render(); }catch(e){}
  try{ renderPainelLocalizacao(); }catch(e){}
  _toast("Foto removida.");
}

