// (equipe Mafra + gestores), calculado na hora para pegar logins criados depois do carregamento.
function gestoresAgendaveis(){ return Object.keys(USUARIOS).filter(k=>USUARIOS[k] && USUARIOS[k].tipo==="gestor"); }
function agendaOwners(){ const s=PESSOAS_AGENDAVEIS.slice(); gestoresAgendaveis().forEach(k=>{ if(s.indexOf(k)<0) s.push(k); }); return s; }
function ehAgendavel(uid){ return PESSOAS_AGENDAVEIS.includes(uid) || (USUARIOS[uid]&&USUARIOS[uid].tipo==="gestor"); }
// gestores do mesmo condomínio/grupo (Le Monde, Trio) formam um time: veem a agenda uns dos outros e se convidam
function grupoDoGestor(uid){ const u=USUARIOS[uid]; if(!u||u.tipo!=="gestor"||!u.condominio) return ""; return condominioPaiDe(u.condominio)||u.condominio; }
function gestoresDoMesmoGrupo(uid){ const g=grupoDoGestor(uid); if(!g) return [uid]; return gestoresAgendaveis().filter(k=>grupoDoGestor(k)===g); }

