window.addEventListener("load", async function(){
  // service worker (rede primeiro): permite reabrir o app sem internet
  try{ if("serviceWorker" in navigator && location.protocol==="https:") navigator.serviceWorker.register("sw.js").catch(function(){}); }catch(e){}
  const h=(location.hash||"").toLowerCase();
  // se é acesso externo (agendamento / status), trata isso e NÃO restaura sessão de login
  if(h.indexOf("#ag=")>=0 || h.indexOf("ag=")>0){
    const cod=(location.hash.split("ag=")[1]||"").split("&")[0];
    if(cod){ try{ mostrarStatusExterno(cod); return; }catch(e){ console.error("status:",e); } }
  }
  if(h.indexOf("vistoria=")>=0){
    const vid=(location.hash.split("vistoria=")[1]||"").split("&")[0];
    if(vid){ try{ abrirVistoriaExterna(vid); return; }catch(e){ console.error("vistoria externa:",e); } }
  }
  if(h.indexOf("vistoria")>=0){
    try{ abrirVistoriaExternaEscolha(); return; }catch(e){ console.error("vistoria externa:",e); }
  }
  if(h.indexOf("agendar")>=0){
    try{ showBooking("externo"); return; }catch(e){ console.error("agendar:",e); }
  }
  // acesso normal: tenta restaurar a sessão (mantém logado ao atualizar a página)
  try{ await CONFIG_PRONTA; }catch(e){}
  try{ restaurarSessao(); }catch(e){}
});

["click","keydown","touchstart"].forEach(function(ev){
  document.addEventListener(ev, function(){ try{ tocarSessao(); }catch(e){} }, {passive:true});
});

var navHist = [];

var _navInterno = false;

window.addEventListener("popstate", function(ev){
  // só intercepta se a pessoa está logada e dentro do app
  if(state && state.userId){
    if(navHist.length){
      // volta uma aba e mantém o app aberto (re-empilha para continuar capturando o "voltar")
      const anterior=navHist.pop();
      state.tab=anterior; render();
      try{ history.pushState({tab:anterior}, "", location.pathname); }catch(e){}
    } else {
      // sem mais histórico interno: NÃO deixa sair do app (importante no iPhone).
      // Volta ao início e re-empilha para continuar segurando o "voltar".
      if(state.tab!=="inicio"){ state.tab="inicio"; render(); }
      try{ history.pushState({tab:"inicio"}, "", location.pathname); }catch(e){}
    }
  }
});

