/* ---- Funções compartilhadas ---- */
function ehEquipeMafra(uid){
  const u=USUARIOS[uid]; if(!u) return false;
  if(uid==="mafra") return false; // superadmin genérico não entra na lista
  return u.tipo==="master" || u.tipo==="sindico" || u.tipo==="funcionario" || (BPO||[]).indexOf(uid)>=0;
}

function equipeMafraIds(){ return Object.keys(USUARIOS).filter(ehEquipeMafra); }

function condsDoGestor(){
  const u=state.user||{};
  if(Array.isArray(u.condominios) && u.condominios.length) return u.condominios.slice();
  return u.condominio?[u.condominio]:[];
}

function gestorCobre(cond){
  if((state.user||{}).tipo!=="gestor") return true;
  const lista=condsDoGestor();
  if(!lista.length) return false;
  return lista.indexOf(cond)>=0;
}

async function condominiosDoSindico(sindicoId){
  try{ const cfg=await loadCondominios(sindicoId); return (cfg.itens||[]).map(c=>c.nome); }catch(e){ return []; }
}

async function podeVer(item){
  const u=state.user, uid=state.userId;
  if(!u) return false;
  if(u.tipo==="master") return true;                 // master vê tudo
  if(uid==="julia") return true;                      // Julia (comunicação) vê tudo
  if(item.autor===uid) return true;                   // o próprio autor vê o seu
  // síndico vê itens dos gestores dos condomínios que ele cuida
  if(u.tipo==="sindico" && item.condominio){
    const meus=await condominiosDoSindico(uid);
    if(meus.includes(item.condominio)) return true;
  }
  return false;
}

