function mondayOf(offset){
  const d = new Date(); d.setHours(0,0,0,0);
  const dow = d.getDay();           // 0=Dom .. 6=Sáb
  const diff = (dow===0? -6 : 1-dow);
  d.setDate(d.getDate()+diff+offset*7);
  return d;
}

function weekKey(offset){ return mondayOf(offset).toISOString().slice(0,10); }

function dateOfDay(offset, dayOff){ const m=mondayOf(offset); m.setDate(m.getDate()+dayOff); return m; }

function fmt(d){ return ("0"+d.getDate()).slice(-2)+"/"+("0"+(d.getMonth()+1)).slice(-2); }

function rangeLabel(offset){
  const a=mondayOf(offset), b=dateOfDay(offset,4);
  return fmt(a)+" a "+fmt(b)+" · "+a.getFullYear();
}

function isCurrentWeek(offset){ return weekKey(offset)===weekKey(0); }

function initSupabase(){
  try{
    if(SUPABASE_URL && SUPABASE_KEY && window.supabase && window.supabase.createClient){
      SB=window.supabase.createClient(SUPABASE_URL, SUPABASE_KEY);
      return true;
    }
  }catch(e){ console.warn("Supabase init falhou:", e); }
  return false;
}

function hasShared(){ try{ return !!(window.storage && typeof window.storage.get==="function" && typeof window.storage.set==="function"); }catch(e){ return false; } }

function lsGet(key){ try{ const v=localStorage.getItem(key); return v!==null?v:(MEM[key]||null); }catch(e){ return MEM[key]||null; } }

function lsSet(key,value){ try{ localStorage.setItem(key,value); }catch(e){} MEM[key]=value; }

function _storeCacheGet(key){
  const e=_storeCache.get(key);
  if(!e) return undefined;
  if(Date.now()-e.t > _CACHE_TTL){ _storeCache.delete(key); return undefined; }
  return e.v;
}

function _storeCacheSet(key,val){ _storeCache.set(key,{v:val,t:Date.now()}); }

function _storeCacheClear(key){ if(key) _storeCache.delete(key); else _storeCache.clear(); }

async function storeGet(key){
  const cached = _storeCacheGet(key);
  if(cached !== undefined) return cached;
  let val = null;
  if(SB){
    try{
      const {data,error}=await SB.from("dados").select("valor").eq("chave",key).maybeSingle();
      if(!error && data && data.valor!=null){ lsSet(key,data.valor); val=data.valor; }
      else if(!error && !data){ val=lsGet(key); }
    }catch(e){ /* cai para local */ }
  }
  if(val===null && hasShared()){
    try{ const r=await window.storage.get(key,true); if(r&&r.value!=null) val=r.value; }catch(e){}
  }
  if(val===null) val=lsGet(key);
  _storeCacheSet(key, val);
  return val;
}

async function storeSet(key,value){
  lsSet(key,value); // cache local sempre
  _storeCacheSet(key, value); // atualiza cache em memória
  let okServidor = true; // só vira false se o servidor principal falhar
  if(SB){
    try{
      const {error}=await SB.from("dados").upsert({chave:key, valor:value, atualizado_em:new Date().toISOString()},{onConflict:"chave"});
      if(error){ console.warn("Supabase save:", error.message); try{ window._lastStoreErr=error.message; }catch(_e){} okServidor=false; }
    }catch(e){ console.warn("Supabase save erro:", e); try{ window._lastStoreErr=String(e&&e.message||e); }catch(_e){} okServidor=false; }
  }
  if(hasShared()){
    try{ await window.storage.set(key,value,true); }
    catch(e){ if(!SB) okServidor=false; }
  }
  // se a gravação no servidor falhou, limpa o cache em memória para que a
  // próxima leitura busque a verdade do servidor (evita "salvou mas voltou")
  if(!okServidor) _storeCacheClear(key);
  return okServidor;
}

async function storeDel(key){
  try{ localStorage.removeItem(key); }catch(e){}
  try{ delete MEM[key]; }catch(e){}
  _storeCacheClear(key);
  let ok=true;
  if(SB){
    try{ const {error}=await SB.from("dados").delete().eq("chave",key); if(error) ok=false; }catch(e){ ok=false; }
  }
  if(hasShared()){
    try{ await window.storage.delete(key,true); }catch(e){}
  }
  return ok;
}

function detectStorageMode(){
  if(SB) STORAGE_MODE="supabase";
  else if(hasShared()) STORAGE_MODE="shared";
  else { try{ localStorage.setItem("mafra:__t","1"); localStorage.removeItem("mafra:__t"); STORAGE_MODE="local"; }catch(e){ STORAGE_MODE="mem"; } }
  return STORAGE_MODE;
}

async function chamarIA(prompt, maxTokens){
  return (await chamarIAInfo(prompt, maxTokens)).texto;
}

// igual à chamarIA, mas devolve também o motivo de parada (para detectar resposta cortada)
async function chamarIAInfo(prompt, maxTokens){
  // Caminho 1: site publicado -> usa o porteiro do Supabase
  if(SUPABASE_URL){
    const url=SUPABASE_URL.replace(/\/$/,"")+"/functions/v1/gerar-ata";
    let r;
    try{
      r=await fetch(url,{
        method:"POST",
        headers:{"Content-Type":"application/json", "Authorization":"Bearer "+SUPABASE_KEY},
        body:JSON.stringify({prompt, max_tokens:maxTokens||2000})
      });
    }catch(netErr){
      throw new Error("Sem conexão com o servidor de IA. Verifique sua internet e tente de novo.");
    }
    let data;
    try{ data=await r.json(); }
    catch(_){ throw new Error("O servidor de IA respondeu de forma inesperada. Tente novamente em instantes."); }
    if(!r.ok || data.error){
      const msg=(data&&data.error&&(data.error.message||data.error))||("Erro "+r.status+" no servidor de IA.");
      throw new Error(typeof msg==="string"?msg:JSON.stringify(msg));
    }
    const texto=(data.content||[]).filter(b=>b.type==="text").map(b=>b.text).join("\n").trim();
    if(!texto) throw new Error("A IA não retornou conteúdo. Tente reformular ou repetir.");
    return {texto, stop:data.stop_reason||""};
  }
  // Caminho 2: dentro do Claude -> API direta (apenas para testes no ambiente Claude)
  const r=await fetch("https://api.anthropic.com/v1/messages",{method:"POST",headers:{"Content-Type":"application/json"},
    body:JSON.stringify({model:"claude-sonnet-4-6",max_tokens:maxTokens||2000,messages:[{role:"user",content:prompt}]})});
  const data=await r.json();
  return {texto:(data.content||[]).filter(b=>b.type==="text").map(b=>b.text).join("\n").trim(), stop:data.stop_reason||""};
}

/* ===== JSON vindo da IA: extração tolerante + conserto de resposta cortada ===== */
// pilha de aberturas {/[ pendentes de um trecho (ignorando o que está dentro de strings)
function _iaPilha(s){
  const pilha=[]; let st=false, es=false;
  for(let i=0;i<s.length;i++){ const c=s[i];
    if(st){ if(es){es=false;} else if(c==="\\"){es=true;} else if(c==='"'){st=false;} continue; }
    if(c==='"'){st=true;continue;}
    if(c==="{"||c==="["){pilha.push(c);}
    else if(c==="}"||c==="]"){pilha.pop();}
  }
  return pilha;
}
// fecha o que ficou aberto num JSON truncado (string aberta, vírgula solta, chave pendurada, {} e [])
function _iaCompletarJSON(s){
  s=String(s||"");
  let emStr=false, escp=false;
  for(let i=0;i<s.length;i++){
    const c=s[i];
    if(emStr){ if(escp){escp=false;} else if(c==="\\"){escp=true;} else if(c==='"'){emStr=false;} continue; }
    if(c==='"') emStr=true;
  }
  if(emStr) s+='"';                                   // terminou no meio de uma string: fecha
  // saneia o final em ciclos até estabilizar
  for(let k=0;k<8;k++){
    const antes=s;
    s=s.replace(/\s+$/,"");
    // "chave": pendurada sem valor
    s=s.replace(/,?\s*"(?:[^"\\]|\\.)*"\s*:\s*$/,"");
    // string final que é CHAVE sem ":" (precedida de { ou ,) — só faz sentido dentro de OBJETO
    const m=s.match(/([{,])\s*"(?:[^"\\]|\\.)*"\s*$/);
    if(m){ const pilha=_iaPilha(s); if(pilha[pilha.length-1]==="{") s=s.slice(0, s.length-(m[0].length-1)); }
    // vírgula solta no fim
    s=s.replace(/,\s*$/,"");
    if(s===antes) break;
  }
  // fecha as aberturas pendentes
  const pilha=_iaPilha(s);
  let fim=""; for(let i=pilha.length-1;i>=0;i--) fim+=(pilha[i]==="{"?"}":"]");
  return s+fim;
}
// limpa cercas de markdown, recorta o JSON e tenta o parse com reparos em cascata
function _iaExtrairJSON(txt, abre){
  txt=String(txt||"").replace(/```json/gi,"").replace(/```/g,"").trim();
  const a=txt.indexOf(abre);
  if(a>=0){ const fecha=(abre==="["?"]":"}"); const b=txt.lastIndexOf(fecha); txt=(b>a)?txt.slice(a,b+1):txt.slice(a); }
  const tenta=function(s){ try{ return JSON.parse(s); }catch(e){ return undefined; } };
  let v=tenta(txt); if(v!==undefined) return v;
  const semQuebra=txt.replace(/\r\n|\r|\n/g,"\\n");      // quebras de linha cruas dentro de strings
  v=tenta(semQuebra); if(v!==undefined) return v;
  v=tenta(_iaCompletarJSON(txt)); if(v!==undefined) return v;
  v=tenta(_iaCompletarJSON(semQuebra)); if(v!==undefined) return v;
  throw new Error("a IA devolveu um formato inesperado — toque em gerar de novo");
}
// gera JSON com a IA; se a resposta vier cortada pelo limite, pede a continuação e emenda
// gera TEXTO/markdown longo; se o servidor cortar por limite e informar, pede a continuação (até 5x) e emenda
async function _iaGerarTextoLongo(prompt, maxTokens){
  let r=await chamarIAInfo(prompt, maxTokens);
  let txt=r.texto, n=0;
  while(r.stop==="max_tokens" && n<5){
    n++;
    try{ r=await chamarIAInfo("Continue EXATAMENTE de onde parou o texto abaixo, sem repetir nada do que já foi escrito e sem comentários — apenas a continuação:\n"+txt, maxTokens); txt+=r.texto; }
    catch(e){ break; }
  }
  return txt;
}
async function _iaGerarJSON(prompt, maxTokens, abre){
  let r=await chamarIAInfo(prompt, maxTokens);
  let txt=r.texto;
  // se o porteiro cortar por limite e informar o motivo, pede a continuação (até 4x) e emenda
  let n=0;
  while(r.stop==="max_tokens" && n<4){
    n++;
    try{
      r=await chamarIAInfo("A resposta JSON abaixo foi cortada no meio. Continue EXATAMENTE do ponto em que parou, sem repetir nada do que já foi escrito, sem comentários e sem markdown — apenas a continuação:\n"+txt, maxTokens);
      txt+=r.texto;
    }catch(e){ break; }
  }
  return _iaExtrairJSON(txt, abre);
}

