function tempoDesde(ts){
  if(!ts) return "nunca acessou";
  const diff=Date.now()-ts;
  const min=Math.floor(diff/60000), h=Math.floor(diff/3600000), dias=Math.floor(diff/86400000);
  const dt=new Date(ts);
  const hora=dt.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"});
  if(min<1) return "agora mesmo";
  if(min<60) return `há ${min} min`;
  if(h<24 && dt.toDateString()===new Date().toDateString()) return `hoje às ${hora}`;
  if(dias===1 || (dias<2 && dt.toDateString()===new Date(Date.now()-86400000).toDateString())) return `ontem às ${hora}`;
  return capit(dt.toLocaleDateString("pt-BR",{day:"2-digit",month:"short"}))+" às "+hora;
}

async function doLogin(){
  const u = document.getElementById("inUser").value.trim().toLowerCase();
  const p = document.getElementById("inPass").value;
  // garante que as senhas atualizadas já vieram do banco antes de conferir
  try{ await CONFIG_PRONTA; }catch(e){}
  let acc = USUARIOS[u];
  if(acc && acc.senha===p){ entrarComoUsuario(u, acc); return; }
  // 2ª tentativa: recarrega a config direto do banco (caso a senha tenha sido
  // trocada em outro aparelho enquanto esta tela já estava aberta)
  try{ _storeCacheClear("mafra:usuarios_extra"); await carregarConfigGlobal(); }catch(e){}
  acc = USUARIOS[u];
  if(acc && acc.senha===p){ entrarComoUsuario(u, acc); return; }
  document.getElementById("loginErr").style.display="block";
  document.getElementById("inPass").value="";
}

function digitalSuportada(){
  return !!(window.PublicKeyCredential && navigator.credentials && navigator.credentials.create);
}

function _b64ToBuf(b64){ const bin=atob(b64.replace(/-/g,"+").replace(/_/g,"/")); const u=new Uint8Array(bin.length); for(let i=0;i<bin.length;i++)u[i]=bin.charCodeAt(i); return u.buffer; }

function _bufToB64(buf){ const u=new Uint8Array(buf); let s=""; for(let i=0;i<u.length;i++)s+=String.fromCharCode(u[i]); return btoa(s).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/,""); }

function lerDigitalLocal(){ try{ const v=localStorage.getItem("mafra:digital"); return v?JSON.parse(v):null; }catch(e){ return null; } }

function salvarDigitalLocal(d){ try{ localStorage.setItem("mafra:digital", JSON.stringify(d)); }catch(e){} }

function limparDigitalLocal(){ try{ localStorage.removeItem("mafra:digital"); }catch(e){} }

function atualizarBotaoDigital(){
  const btn=document.getElementById("btnEntrarDigital");
  if(!btn) return;
  const d=lerDigitalLocal();
  if(d && d.uid && d.credId && digitalSuportada()){
    btn.style.display="block";
    const us=USUARIOS[d.uid];
    btn.textContent = "🔒 Entrar com digital" + (us? " ("+us.nome.split(" ")[0]+")" : "");
  } else {
    btn.style.display="none";
  }
}

async function ativarDigital(){
  if(!state.userId){ alert("Faça login primeiro."); return; }
  if(!digitalSuportada()){ alert("Este aparelho ou navegador não suporta login por digital."); return; }
  try{
    const uid=state.userId;
    const desafio=crypto.getRandomValues(new Uint8Array(32));
    const userId=new TextEncoder().encode(uid);
    const cred=await navigator.credentials.create({
      publicKey:{
        challenge: desafio,
        rp: { name: "Gestão Mafra" },
        user: { id: userId, name: uid, displayName: state.user.nome },
        pubKeyCredParams: [ {type:"public-key",alg:-7}, {type:"public-key",alg:-257} ],
        authenticatorSelection: { userVerification: "preferred" }, // pede biometria do aparelho
        timeout: 60000,
        attestation: "none"
      }
    });
    if(!cred){ alert("Não foi possível cadastrar a digital."); return; }
    salvarDigitalLocal({ uid: uid, credId: _bufToB64(cred.rawId), nome: state.user.nome });
    alert("✅ Acesso por digital ativado neste aparelho!\n\nNa próxima vez, é só tocar em \"Entrar com digital\".");
  }catch(err){
    if(err && err.name==="NotAllowedError"){ alert("Cadastro de digital cancelado."); }
    else { alert("Não foi possível ativar a digital: "+(err.message||err)); }
  }
}

function oferecerDigitalSeNovo(){
  if(!digitalSuportada()) return;
  if(!state.userId) return;
  const d=lerDigitalLocal();
  if(d && d.uid===state.userId) return; // já tem digital pra mim neste aparelho
  // respeita quem já recusou neste aparelho (não fica insistindo)
  let recusou=false;
  try{ recusou = localStorage.getItem("mafra:digital_recusou:"+state.userId)==="1"; }catch(e){}
  if(recusou) return;
  setTimeout(()=>{
    const ok=confirm("🔒 Ativar acesso por digital?\n\nNeste aparelho, você pode entrar com a digital em vez de digitar a senha toda vez.\n\nDeseja ativar agora?");
    if(ok){
      ativarDigital();
    } else {
      try{ localStorage.setItem("mafra:digital_recusou:"+state.userId, "1"); }catch(e){}
    }
  }, 900);
}

function secaoDigitalHTML(){
  if(!digitalSuportada()){
    return `<div style="border-top:1px solid var(--line2);margin-top:16px;padding-top:14px">
      <div class="lbl-mini" style="margin-bottom:4px">🔒 Acesso por digital</div>
      <div style="font-size:12px;color:var(--muted)">Este aparelho ou navegador não suporta login por digital.</div>
    </div>`;
  }
  const d=lerDigitalLocal();
  const ativadaPraMim = d && d.uid===state.userId;
  if(ativadaPraMim){
    return `<div style="border-top:1px solid var(--line2);margin-top:16px;padding-top:14px">
      <div class="lbl-mini" style="margin-bottom:6px">🔒 Acesso por digital</div>
      <div style="font-size:12px;color:#2F7D4F;font-weight:600;margin-bottom:10px">✅ Ativado neste aparelho. Você pode entrar tocando o dedo.</div>
      <button class="btn-cancel" style="width:100%" onclick="desativarDigital()">Desativar digital neste aparelho</button>
    </div>`;
  }
  return `<div style="border-top:1px solid var(--line2);margin-top:16px;padding-top:14px">
    <div class="lbl-mini" style="margin-bottom:6px">🔒 Acesso por digital</div>
    <div style="font-size:12px;color:var(--muted);margin-bottom:10px">Ative para entrar com a digital neste aparelho, sem digitar a senha toda vez.</div>
    <button class="btn-primary" style="width:100%;background:#1f3354" onclick="ativarDigitalNoModal()">🔒 Ativar acesso por digital</button>
  </div>`;
}

async function ativarDigitalNoModal(){
  await ativarDigital();
  const d=lerDigitalLocal();
  if(d && d.uid===state.userId){ closeModal(); }
}

function desativarDigital(){
  if(!confirm("Desativar o acesso por digital neste aparelho? Você voltará a entrar com senha.")) return;
  limparDigitalLocal();
  atualizarBotaoDigital();
  closeModal();
  alert("Acesso por digital desativado neste aparelho.");
}

async function entrarComDigital(){
  const d=lerDigitalLocal();
  if(!d || !d.uid || !d.credId){ alert("Nenhuma digital cadastrada neste aparelho. Entre com sua senha primeiro e ative a digital."); return; }
  if(!digitalSuportada()){ alert("Este aparelho não suporta login por digital."); return; }
  try{ await CONFIG_PRONTA; }catch(e){}
  const acc=USUARIOS[d.uid];
  if(!acc){ alert("Usuário não encontrado. Faça login com senha."); limparDigitalLocal(); atualizarBotaoDigital(); return; }
  try{
    const desafio=crypto.getRandomValues(new Uint8Array(32));
    const assertion=await navigator.credentials.get({
      publicKey:{
        challenge: desafio,
        allowCredentials: [ { type:"public-key", id: _b64ToBuf(d.credId) } ],
        userVerification: "preferred",
        timeout: 60000
      }
    });
    if(assertion){
      // biometria confirmada pelo aparelho → entra
      entrarComoUsuario(d.uid, acc);
    }
  }catch(err){
    if(err && err.name==="NotAllowedError"){ alert("Não reconhecido. Você pode entrar com sua senha."); }
    else { alert("Falha no login por digital: "+(err.message||err)+"\n\nEntre com sua senha."); }
  }
}

