function limparSessao(){ try{ localStorage.removeItem("mafra:sessao"); }catch(e){} }

function restaurarSessao(){
  try{
    const raw = localStorage.getItem("mafra:sessao");
    if(!raw) return false;
    const s = JSON.parse(raw);
    if(!s || !s.uid || !s.ts) return false;
    // expira após 12h sem atividade
    if(Date.now() - s.ts > SESSAO_MAX_MS){ limparSessao(); return false; }
    const acc = USUARIOS[s.uid];
    if(!acc) { limparSessao(); return false; }
    entrarComoUsuario(s.uid, acc, true); // true = silencioso (sem reabrir backup etc.)
    return true;
  }catch(e){ return false; }
}

function entrarComoUsuario(u, acc, silencioso){
  state.userId=u; state.user=acc; state.semana=0; state.tab="inicio";
  const le=document.getElementById("loginErr"); if(le) le.style.display="none";
  document.getElementById("login").classList.add("hidden");
  document.getElementById("app").classList.remove("hidden");
  document.getElementById("topName").textContent=acc.nome;
  try{ _pintarTopAvatar(); carregarPerfis().then(function(){ try{_pintarTopAvatar();}catch(e){} }); }catch(e){}
  try{ window._permCache=window._permCache||{}; loadPermissoes().then(function(){ try{ render(); }catch(e){} }); }catch(e){}
  document.getElementById("topRole").innerHTML = acc.tipo==="master"
    ? esc(acc.cargo)+' <span class="tag-master">Master</span>'
    : esc(acc.cargo || (acc.tipo==="gestor"?"Gestor de Condomínio":acc.tipo==="sindico"?"Síndico Operacional":acc.tipo==="helpdesk"?"Help Condo":"Funcionário(a)"))+(acc.tipo==="gestor"&&acc.condominio?` · ${esc(acc.condominio)}`:"");
  detectStorageMode();
  registrarAcesso(u);
  salvarSessao(u);
  // entrada base no histórico do navegador (para o botão voltar do aparelho funcionar dentro do app)
  try{ history.pushState({tab:"inicio"}, "", location.pathname); }catch(e){}
  render();
  mostrarBiaBtn(true);
  if(!silencioso){ try{ verificarBackupMensal(); }catch(e){} }
  if(!silencioso){ try{ oferecerDigitalSeNovo(); }catch(e){} }
  // Sistema de lembrete de check-in + badge no ícone
  try{ iniciarVerificacaoCheckinLembrete(); }catch(e){}
  try{ atualizarBadgeApp(); }catch(e){}
  // build 126: check-in assistido por GPS + lembrete de check-out + fechamento automático em 24h
  try{ setTimeout(function(){ try{ ckAssistente("login"); }catch(e){} }, 2500); }catch(e){}
  try{ setTimeout(function(){ try{ _liChecarLembretes(); }catch(e){} }, 4000); }catch(e){}
  if(STORAGE_MODE!=="supabase" && STORAGE_MODE!=="shared"){
    const aviso=document.getElementById("storageWarn");
    if(aviso) aviso.style.display="block";
    const md=document.getElementById("storageMode");
    if(md) md.textContent="(modo atual: "+STORAGE_MODE+")";
  }
}

function tickRelogio(){
  const ag=new Date();
  const h=document.getElementById("tcHora"), dd=document.getElementById("tcData");
  if(h) h.textContent=ag.toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"});
  if(dd) dd.textContent=capit(ag.toLocaleDateString("pt-BR",{weekday:"short",day:"2-digit",month:"short"}));
}

function logout(){ state={userId:null,user:null,semana:0,tab:"tarefas"};
  limparSessao();
  document.getElementById("app").classList.add("hidden");
  document.getElementById("booking").classList.add("hidden");
  document.getElementById("login").classList.remove("hidden");
  document.getElementById("inUser").value=""; document.getElementById("inPass").value="";
  mostrarBiaBtn(false); fecharBia(); biaState.hist=[];
  try{ atualizarBotaoDigital(); }catch(e){}
}

function render(){
  document.getElementById("subnav").innerHTML = tabBarHTML();
  if(state.tab==="inicio") renderInicio();
  else if(state.tab==="relatorios") renderRelatorios();
  else if(state.tab==="calendario") renderCalendario();
  else if(state.tab==="hoje") renderHoje();
  else if(state.tab==="gravacoes") renderGravacoes();
  else if(state.tab==="comunicados") renderComunicados();
  else if(state.tab==="ocorrencias") renderOcorrencias();
  else if(state.tab==="vistoria") renderVistoria();
  else if(state.tab==="gerenciar") renderGerenciar();
  else if(state.tab==="escritorio") renderEscritorio();
  else if(state.tab==="manual") renderManual();
  else if(state.tab==="procedimentos") renderProcedimentos();
  else if(state.tab==="checklist") renderChecklists();
  else if(state.tab==="videos") renderVideos();
  else if(state.tab==="notas") renderNotas();
  else if(state.tab==="helpdesk") renderHelpdesk();
  else if(state.tab==="metricas") renderMetricas();
  else if(state.tab==="sindicos") renderGrupo("sindicos");
  else if(state.tab==="bpo") renderGrupo("bpo");
  else if(typeof _liModoAtivo==="function" && _liModoAtivo()) renderListas();   // build 129: aba Tarefas em modo Listas (To Do)
  else if(state.user.tipo==="sindico") renderSindico();
  else renderLideranca();
  atualizaSino();
}

