/* ===== TELA DE PERMISSÕES E ACESSOS (somente master) ===== */
function abrirPermissoesPerfil(perfil){
  if(!state.user || state.user.tipo!=="master"){ return; }
  perfil = (PERM_PERFIS.find(function(p){return p.id===perfil;})) ? perfil : "sindico";
  const perm = _permPerfil(perfil);
  const perfilOpts = PERM_PERFIS.map(function(p){ return `<option value="${p.id}" ${p.id===perfil?"selected":""}>${esc(p.lbl)}</option>`; }).join("");
  const linhas = PERM_MODULOS.map(function(mod){
    const on = !!perm[mod.id];
    const lock = (perfil==="master" && mod.id==="gerenciar");
    return `<label class="perm-row${lock?' perm-lock':''}">
      <span class="perm-ic">${ico(mod.ic)}</span>
      <span class="perm-txt"><b>${esc(mod.lbl)}</b>${mod.desc?`<small>${esc(mod.desc)}</small>`:""}</span>
      <input type="checkbox" class="perm-chk" data-mod="${mod.id}" ${on?"checked":""} ${lock?"disabled":""}>
      <span class="perm-sw"></span>
    </label>`;
  }).join("");
  document.getElementById("modalMount").innerHTML=`<div class="overlay" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:560px">
    <div class="modal-head"><h3>${ico('gerenciar')} Permissões e Acessos</h3><button class="x" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <label class="lbl">Perfil</label>
      <select id="permPerfilSel" class="inp" onchange="abrirPermissoesPerfil(this.value)">${perfilOpts}</select>
      <p style="color:var(--muted);font-size:12.5px;margin:10px 0 14px;line-height:1.5">Marque os módulos que o perfil <b>${esc(_perfLbl(perfil))}</b> pode acessar. Vale para <b>todos os usuários</b> deste perfil. A tela <b>Início</b> é sempre visível.${perfil==="master"?' <br><span style="color:var(--gold)">O módulo Gerenciar fica travado para o Master, para não bloquear a administração.</span>':''}</p>
      <div class="perm-lista">${linhas}</div>
      <div class="modal-foot" style="margin-top:18px;gap:8px">
        <button class="btn-ghost" onclick="_permRestaurar('${perfil}')">↩ Restaurar padrão</button>
        <button class="btn-gold" style="flex:1" onclick="_permSalvar('${perfil}')">💾 Salvar permissões</button>
      </div>
    </div>
  </div></div>`;
}
async function _permSalvar(perfil){
  const map={};
  document.querySelectorAll(".perm-chk").forEach(function(c){ map[c.getAttribute("data-mod")] = c.checked?1:0; });
  if(perfil==="master") map["gerenciar"]=1;
  const perm = await loadPermissoes();
  perm[perfil]=map;
  const ok = await salvarPermissoes(perm);
  if(!ok){ alert("Não consegui salvar as permissões no servidor.\n\nVerifique a internet e tente de novo."+(window._lastStoreErr?("\n\nDetalhe técnico: "+window._lastStoreErr):"")); return; }
  closeModal();
  _toast("✅ Permissões do perfil “"+_perfLbl(perfil)+"” salvas.");
  try{ render(); }catch(e){}
}
async function _permRestaurar(perfil){
  if(!confirm("Restaurar as permissões PADRÃO do perfil "+_perfLbl(perfil)+"?\n\nIsso desfaz as customizações deste perfil.")) return;
  const perm = await loadPermissoes();
  delete perm[perfil];
  await salvarPermissoes(perm);
  _toast("Permissões padrão restauradas.");
  abrirPermissoesPerfil(perfil);
  try{ render(); }catch(e){}
}

/* toast discreto (avisos rápidos, ex.: ata pronta em segundo plano) */
function _toast(msg, ms){
  try{
    var t=document.createElement("div"); t.className="toast-mini"; t.innerHTML=msg;
    document.body.appendChild(t);
    requestAnimationFrame(function(){ t.classList.add("on"); });
    setTimeout(function(){ t.classList.remove("on"); setTimeout(function(){ if(t.parentNode) t.parentNode.removeChild(t); }, 350); }, ms||4200);
  }catch(e){}
}

function openMenu(){ var d=document.getElementById("drawer"), o=document.getElementById("drawerOv"); if(d) d.classList.add("open"); if(o) o.classList.add("open"); }
function closeMenu(){ var d=document.getElementById("drawer"), o=document.getElementById("drawerOv"); if(d) d.classList.remove("open"); if(o) o.classList.remove("open"); }
function toggleMenu(){ var d=document.getElementById("drawer"); if(d && d.classList.contains("open")) closeMenu(); else openMenu(); }

/* ============================================================
   CONTROLE DE PERMISSÕES POR PERFIL
   O master define quais MÓDULOS cada perfil pode acessar.
   Padrão (PERM_DEFAULT) espelha exatamente o comportamento atual.
   Guardado em "mafra:permissoes" = { perfil: {modulo:1|0} } (compartilhado).
   ============================================================ */
const PERM_PERFIS = [
  {id:"master",      lbl:"Master"},
  {id:"gestor",      lbl:"Gestor de Condomínio"},
  {id:"sindico",     lbl:"Síndico Operacional"},
  {id:"funcionario", lbl:"BPO / Administrativo"},
  {id:"helpdesk",    lbl:"Help Condo"}
];
// ordem = ordem das abas no menu. "inicio" é fixo (sempre visível, não entra na lista).
const PERM_MODULOS = [
  {id:"tarefas",     ic:"tarefas",     lbl:"Tarefas"},
  {id:"sindicos",    ic:"sindicos",    lbl:"Síndicos Operacionais", desc:"Visão de gestão das tarefas dos síndicos"},
  {id:"bpo",         ic:"bpo",         lbl:"BPO", desc:"Visão de gestão das tarefas do administrativo"},
  {id:"calendario",  ic:"calendario",  lbl:"Calendário"},
  {id:"relatorios",  ic:"relatorios",  lbl:"Relatório Gerencial"},
  {id:"helpdesk",    ic:"helpdesk",    lbl:"Help Condo"},
  {id:"gravacoes",   ic:"gravacoes",   lbl:"Reuniões & Planos de Ação"},
  {id:"metricas",    ic:"metricas",    lbl:"Métricas"},
  {id:"manual",      ic:"manual",      lbl:"Manual Boas-Vindas"},
  {id:"procedimentos", ic:"procedimentos", lbl:"Manual de Procedimentos", desc:"Manual operacional editável por condomínio, por tipo (comercial, residencial, misto, loteamento)"},
  {id:"checklist", ic:"checklist", lbl:"Check List", desc:"Termos e checklists por condomínio (salão de festas, churrasqueira, estoque de limpeza, patrimônio) com impressão e assinaturas"},
  {id:"videos", ic:"videos", lbl:"Vídeos e Tutoriais", desc:"Vídeos e tutoriais de uso do sistema e dos procedimentos"},
  {id:"escritorio",  ic:"escritorio",  lbl:"Escritório"},
  {id:"agendamento", ic:"link",        lbl:"Link de Agendamento", desc:"Botão de agendar reunião"},
  {id:"gerenciar",   ic:"gerenciar",   lbl:"Gerenciar", desc:"Administração: usuários, permissões, condomínios, backup"}
];
const PERM_DEFAULT = {
  master:      {tarefas:1,sindicos:1,bpo:1,calendario:1,comunicados:0,relatorios:1,helpdesk:1,vistoria:0,gravacoes:1,metricas:1,notas:0,manual:1,procedimentos:1,checklist:1,videos:1,escritorio:1,agendamento:1,gerenciar:1},
  gestor:      {tarefas:1,sindicos:0,bpo:0,calendario:1,comunicados:0,relatorios:1,helpdesk:1,vistoria:0,gravacoes:1,metricas:1,notas:0,manual:1,procedimentos:1,checklist:1,videos:1,escritorio:0,agendamento:0,gerenciar:0},
  sindico:     {tarefas:1,sindicos:0,bpo:0,calendario:1,comunicados:0,relatorios:1,helpdesk:1,vistoria:0,gravacoes:1,metricas:1,notas:0,manual:1,procedimentos:1,checklist:1,videos:1,escritorio:0,agendamento:1,gerenciar:0},
  funcionario: {tarefas:1,sindicos:0,bpo:0,calendario:1,comunicados:0,relatorios:1,helpdesk:1,vistoria:0,gravacoes:1,metricas:1,notas:0,manual:1,procedimentos:1,checklist:1,videos:1,escritorio:1,agendamento:1,gerenciar:0},
  helpdesk:    {tarefas:1,sindicos:0,bpo:0,calendario:1,comunicados:0,relatorios:0,helpdesk:1,vistoria:0,gravacoes:0,metricas:1,notas:0,manual:0,procedimentos:0,checklist:0,videos:1,escritorio:0,agendamento:0,gerenciar:0}
};
async function loadPermissoes(){
  try{ const v=await storeGet("mafra:permissoes"); if(v){ const o=JSON.parse(v); if(o&&typeof o==="object"){ window._permCache=o; return o; } } }catch(e){}
  window._permCache = window._permCache || {};
  return window._permCache;
}
async function salvarPermissoes(perm){ window._permCache=perm||{}; return await storeSet("mafra:permissoes", JSON.stringify(perm||{})); }
function _permPerfil(perfil){
  const def = PERM_DEFAULT[perfil] || {};
  const saved = (window._permCache && window._permCache[perfil]) || null;
  return saved ? Object.assign({}, def, saved) : Object.assign({}, def);
}
function _podeModulo(perfil, modId){
  if(modId==="inicio") return true;
  if(perfil==="master" && modId==="gerenciar") return true; // trava: master nunca perde a administração
  return !!_permPerfil(perfil)[modId];
}
function _perfLbl(p){ const o=PERM_PERFIS.find(x=>x.id===p); return o?o.lbl:p; }

function tabBarHTML(){
  const t=state.tab;
  const perfil=(state.user&&state.user.tipo)||"sindico";
  let tabs=`<button class="tab ${t==='inicio'?'on':''}" onclick="setTab('inicio')">${ico('inicio')} Início</button>`;
  let linkBtn="";
  PERM_MODULOS.forEach(function(mod){
    if(!_podeModulo(perfil, mod.id)) return;
    if(mod.id==="agendamento"){ linkBtn=`<button class="tab-link" onclick="showBooking('app')">${ico('link')} Agendamento</button>`; return; }
    const badge = mod.id==="comunicados" ? '<span class="tab-badge" id="tabBadgeCom" style="display:none"></span>' : "";
    tabs+=`<button class="tab ${t===mod.id?'on':''}" onclick="setTab('${mod.id}')">${ico(mod.ic)} ${mod.lbl}${badge}</button>`;
  });
  return `<div class="tabs">${tabs}${linkBtn}</div>`;
}

function setTab(t){
  // segurança: se o perfil não tem permissão para o módulo, volta ao Início
  if(t!=="inicio" && state.user && !_podeModulo(state.user.tipo, t)){
    _toast && _toast("Seu perfil não tem acesso a este módulo.");
    t="inicio";
  }
  if(state.tab && state.tab!==t){
    navHist.push(state.tab); if(navHist.length>30) navHist.shift();
    // adiciona uma entrada no histórico do navegador (para o botão voltar do celular)
    if(!_navInterno){ try{ history.pushState({tab:t}, "", location.pathname+location.hash); }catch(e){} }
  }
  _navInterno=false;
  state.tab=t; render(); closeMenu();
}

function irParaInicio(){ closeMenu();
  if(!state.userId) return;        // só funciona logado
  navHist=[];
  setTab("inicio");
}

function voltarTela(){
  if(navHist.length){
    const anterior=navHist.pop();
    _navInterno=true;       // não empilha de novo
    state.tab=anterior; render();
    return true;
  }
  return false; // não tinha pra onde voltar
}

function changeWeek(delta){ state.semana+=delta; render(); }

function goToday(){ state.semana=0; render(); }

function irParaSemanaDaData(dateStr){
  if(!dateStr) return;
  const [a,m,d]=dateStr.split("-").map(Number);
  const alvo=new Date(a, m-1, d); alvo.setHours(0,0,0,0);
  const seg0=mondayOf(0);                              // segunda da semana atual
  const diffDias=Math.round((alvo-seg0)/86400000);
  state.semana=Math.floor(diffDias/7);                 // offset de semanas
  render();
}

function escolherSemana(btn){
  const inp=document.createElement("input");
  inp.type="date"; inp.style.position="fixed"; inp.style.left="-9999px";
  // começa na segunda-feira da semana exibida
  inp.value=ymd(mondayOf(state.semana));
  document.body.appendChild(inp);
  inp.addEventListener("change",()=>{ const v=inp.value; inp.remove(); if(v) irParaSemanaDaData(v); });
  inp.addEventListener("blur",()=>{ setTimeout(()=>inp.remove(),300); });
  // abre o calendário nativo
  if(inp.showPicker){ try{ inp.showPicker(); return; }catch(e){} }
  inp.focus(); inp.click();
}

function statusLabel(s){ return s==="concluido"?"Concluído":s==="em_andamento"?"Em andamento":"Planejado"; }

function statusCls(s){ return s==="concluido"?"s-concluido":s==="em_andamento"?"s-andamento":"s-planejado"; }

function closeModal(){ try{ if(typeof _ditStop==="function") _ditStop(true); }catch(e){} try{ window._gravAbertaId=null; }catch(e){} document.getElementById("modalMount").innerHTML=""; }

/* ============================================================
   DITADO POR VOZ GENÉRICO (reutilizável em qualquer campo)
   Mesma calibragem robusta usada na Vistoria, incluindo a
   blindagem do Chrome no Android (que reenvia finais acumulados).
   Uso: <button onclick="ditarToggle('idDoTextarea', this)">🎙️ Ditar</button>
   ============================================================ */
let _ditState=null;
function ditarToggle(taId, btn){
  if(_ditState && _ditState.taId===taId){ _ditStop(true); return; }
  if(_ditState) _ditStop(true);
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if(!SR){ alert("O ditado por voz não é suportado neste navegador.\n\nUse o Chrome (Android) ou o Safari atualizado (iPhone/iPad) — ou digite normalmente."); return; }
  if(navigator.onLine===false){ alert("O ditado por voz precisa de internet.\n\nSem rede, digite normalmente — o texto fica salvo no aparelho e sobe quando a conexão voltar."); return; }
  const ta=document.getElementById(taId); if(!ta) return;
  const base=ta.value?(ta.value.replace(/\s+$/,"")+" "):"";
  const ehAndroid=/android/i.test(navigator.userAgent||"");
  const rec=new SR(); rec.lang="pt-BR"; rec.continuous=!ehAndroid; rec.interimResults=true; rec.maxAlternatives=1;
  _ditState={taId, rec, btn, ta, base, finalTxt:"", interim:"", ult:"", ativo:true};
  rec.onresult=function(e){
    if(!_ditState) return;
    let interim="";
    for(let i=e.resultIndex;i<e.results.length;i++){
      const r=e.results[i]; const txt=(r[0]&&r[0].transcript||"").trim(); if(!txt) continue;
      if(r.isFinal){
        const ult=_ditState.ult||"";
        if(txt===ult){ /* mesmo final reenviado: ignora */ }
        else if(ult && txt.indexOf(ult)===0){
          let f=_ditState.finalTxt||""; f=f.slice(0, Math.max(0, f.length-ult.length)).replace(/\s+$/,"");
          const sep=(f && !/[\s.,;:!?]$/.test(f))?" ":""; _ditState.finalTxt=f+sep+txt; _ditState.ult=txt;
        }
        else if(ult && ult.indexOf(txt)===0){ /* versão encolhida: ignora */ }
        else{ const sep=(_ditState.finalTxt && !/[\s.,;:!?]$/.test(_ditState.finalTxt))?" ":""; _ditState.finalTxt=(_ditState.finalTxt||"")+sep+txt; _ditState.ult=txt; }
      }else{ interim+=(interim?" ":"")+txt; }
    }
    _ditState.interim=interim; _ditUpdate();
  };
  rec.onerror=function(e){
    if(e && (e.error==="no-speech"||e.error==="aborted")) return;
    if(e && (e.error==="not-allowed"||e.error==="service-not-allowed")){ alert("Permita o acesso ao microfone para ditar."); _ditStop(false); }
  };
  rec.onend=function(){
    if(_ditState && _ditState.ativo && _ditState.taId===taId){
      _ditState.ult="";
      try{ rec.start(); }catch(_){ setTimeout(function(){ try{ if(_ditState && _ditState.ativo && _ditState.taId===taId) rec.start(); }catch(__){} },250); }
    }
  };
  try{ rec.start(); }catch(e){ alert("Não consegui iniciar o microfone. Tente de novo."); _ditState=null; return; }
  if(btn){ btn.classList.add("rec"); btn.dataset.lbl=btn.innerHTML; btn.innerHTML="■ Parar ditado"; }
}
function _ditUpdate(){
  const s=_ditState; if(!s || !s.ta) return;
  let t=(s.base||"")+(s.finalTxt||"");
  if(s.interim){ const sep=(t && !/[\s.,;:!?]$/.test(t))?" ":""; t+=sep+s.interim; }
  s.ta.value=t;
}
function _ditStop(salvar){
  const s=_ditState; if(!s) return; _ditState=null;
  s.ativo=false; try{ s.rec.onend=null; s.rec.stop(); }catch(e){}
  if(s.btn){ s.btn.classList.remove("rec"); s.btn.innerHTML=s.btn.dataset.lbl||"🎙️ Ditar"; }
  if(s.ta && salvar){ s.ta.value=((s.base||"")+(s.finalTxt||"")).replace(/\s+/g," ").trim(); }
}

function abrirTrocarSenha(){
  if(!state.userId) return;
  document.getElementById("modalMount").innerHTML=`<div class="overlay" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:400px">
    <div class="modal-head"><h3>🔑 Minha conta</h3><button class="x" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <p class="book-sub" style="margin-top:0">Defina uma senha pessoal. Você usará ela no próximo login.</p>
      <div class="field" style="margin-bottom:12px">
        <label class="lbl-mini">Senha atual</label>
        <input type="password" id="psAtual" class="inp" placeholder="Digite sua senha atual" autocomplete="current-password">
      </div>
      <div class="field" style="margin-bottom:12px">
        <label class="lbl-mini">Nova senha</label>
        <input type="password" id="psNova" class="inp" placeholder="Mínimo 6 caracteres" autocomplete="new-password">
      </div>
      <div class="field" style="margin-bottom:8px">
        <label class="lbl-mini">Confirmar nova senha</label>
        <input type="password" id="psConf" class="inp" placeholder="Repita a nova senha" autocomplete="new-password">
      </div>
      <div id="psErro" style="display:none;background:#FCE9E6;color:#C0392B;font-size:12.5px;font-weight:600;padding:9px 12px;border-radius:8px;margin-bottom:8px"></div>
      <div class="modal-foot">
        <button class="btn-cancel" onclick="closeModal()">Cancelar</button>
        <button class="btn-primary" onclick="confirmarTrocaSenha()">Salvar nova senha</button>
      </div>
      ${secaoDigitalHTML()}
    </div></div></div>`;
  setTimeout(()=>{ const a=document.getElementById("psAtual"); if(a) a.focus(); },100);
}

async function confirmarTrocaSenha(){
  const atual=document.getElementById("psAtual").value;
  const nova=document.getElementById("psNova").value;
  const conf=document.getElementById("psConf").value;
  const erro=document.getElementById("psErro");
  const mostrarErro=(msg)=>{ erro.textContent=msg; erro.style.display="block"; };

  const acc=USUARIOS[state.userId];
  if(!acc){ mostrarErro("Usuário não encontrado."); return; }
  if(atual!==acc.senha){ mostrarErro("A senha atual está incorreta."); return; }
  if(nova.length<6){ mostrarErro("A nova senha precisa ter pelo menos 6 caracteres."); return; }
  if(nova!==conf){ mostrarErro("A confirmação não confere com a nova senha."); return; }
  if(nova===atual){ mostrarErro("A nova senha deve ser diferente da atual."); return; }

  // aplica e salva
  USUARIOS[state.userId].senha=nova;
  try{
    await salvarUsuariosExtra();
    closeModal();
    alert("✅ Senha alterada com sucesso!\n\nUse a nova senha no próximo login.");
  }catch(e){
    mostrarErro("Erro ao salvar. Tente novamente.");
  }
}

async function loadRelatorios(fresh){
  // fresh=true: ignora o cache em memória e busca a versão mais recente do servidor
  // (importante antes de salvar/alterar status, para não ressuscitar dados antigos)
  if(fresh) _storeCacheClear("mafra:relatorios");
  try{ const v=await storeGet("mafra:relatorios"); if(v) return JSON.parse(v); }catch(e){}
  return {list:[]};
}

// ---- Indicador de carregamento (os dados dos relatórios são pesados; sem isso o botão parece "morto") ----
function mostrarCarregandoRel(msg){
  let el=document.getElementById("relLoading");
  if(!el){ el=document.createElement("div"); el.id="relLoading"; el.className="rel-loading"; document.body.appendChild(el); }
  el.innerHTML='<div class="rel-loading-box"><div class="rel-loading-spin"></div><div>'+esc(msg||"Carregando…")+'</div></div>';
  el.style.display="flex";
}
function esconderCarregandoRel(){ const el=document.getElementById("relLoading"); if(el) el.style.display="none"; }

// busca a versão mais recente do relatório no servidor mostrando o indicador na tela
async function _relCarregarFresh(id, msg){
  mostrarCarregandoRel(msg||"Carregando o relatório…");
  try{
    const d=await loadRelatorios(true);
    const r=(d.list||[]).find(x=>x.id===id);
    return {d, r};
  } finally { esconderCarregandoRel(); }
}

/* ============================================================
   FOTOS SEPARADAS DO ÍNDICE
   Antes, TODOS os relatórios com TODAS as fotos moravam numa única chave
   ("mafra:relatorios"). Essa chave cresceu além do que o servidor aceita gravar
   e as gravações passaram a falhar. Agora:
   - "mafra:relatorios"      = índice LEVE (dados, status, histórico — sem fotos)
   - "mafra:relfotos:<id>"   = as fotos daquele relatório (uma chave por relatório)
   Relatórios antigos são migrados automaticamente na primeira gravação.
   ============================================================ */
function _relFid(){ return "f"+Date.now().toString(36)+Math.random().toString(36).slice(2,7); }
function _fotoEmbutida(e){ return !!(e && e.foto && String(e.foto).indexOf("data:")===0); }
function _fotoDepEmbutida(e){ return !!(e && e.fotoDepois && String(e.fotoDepois).indexOf("data:")===0); }
function _fotoExtraEmbutida(e){ return !!(e && Array.isArray(e.fotosExtras) && e.fotosExtras.some(x=>x && x.foto && String(x.foto).indexOf("data:")===0)); }
function _fotoEmbutidaAlguma(e){ return _fotoEmbutida(e) || _fotoDepEmbutida(e) || _fotoExtraEmbutida(e); }
function _relTemFotoEmbutida(r){
  return ["registros","reunioes"].some(s=>(r&&r[s]||[]).some(_fotoEmbutidaAlguma));
}

// junta as fotos embutidas do relatório num mapa {fid: base64} (gera fid onde faltar)
function _relColetarFotos(r){
  const mapa={};
  for(const s of ["registros","reunioes"]){
    for(const e of (r[s]||[])){
      if(_fotoEmbutida(e)){ if(!e.fid) e.fid=_relFid(); mapa[e.fid]=e.foto; }
      if(_fotoDepEmbutida(e)){ if(!e.fidDepois) e.fidDepois=_relFid(); mapa[e.fidDepois]=e.fotoDepois; }
      if(Array.isArray(e.fotosExtras)){ for(const ex of e.fotosExtras){ if(ex && ex.foto && String(ex.foto).indexOf("data:")===0){ if(!ex.fid) ex.fid=_relFid(); mapa[ex.fid]=ex.foto; } } }
    }
  }
  return mapa;
}

// tamanho máximo de cada pedaço de fotos (~600KB) — bem abaixo de limites de payload/timeout do servidor.
// Gravar TODAS as fotos numa chave só fazia o upload estourar e falhar quando o relatório tinha muitas fotos.
const _REL_CHUNK_MAX = 600000;

// grava as fotos do relatório DIVIDIDAS EM PEDAÇOS pequenos (cada um numa chave),
// com 1 nova tentativa por pedaço. Meta "mafra:relfotos:<id>" guarda a contagem de pedaços.
async function _relGravarFotosDe(r){
  const kmeta="mafra:relfotos:"+r.id;
  const embutidas=_relColetarFotos(r);
  // 🔒 build 122 — REGRA DE OURO: o sistema nunca apaga uma foto que não
  // conseguiu LER por inteiro. Antes, editar com conexão fraca fazia o app
  // regravar só as fotos que carregaram na tela — e as demais eram apagadas
  // do servidor no salvar. Agora: lê o que já existe e PRESERVA; se a leitura
  // não vier completa, nada antigo é tocado — as fotos novas são ACRESCENTADAS.
  let antigos=0, legado=null;
  try{ const v=await storeGet(kmeta); if(v){ const o=JSON.parse(v)||{}; if(o.chunks) antigos=o.chunks; else if(o.fotos) legado=o.fotos; } }catch(e){}
  if(!Object.keys(embutidas).length && !legado) return true; // nada novo e nada a migrar — e nada é apagado
  const mapa=Object.assign({}, legado||{}, embutidas);
  let leituraCompleta=true; const doServidor={};
  for(let i2=0;i2<antigos;i2++){
    const kc=kmeta+":c"+i2;
    try{
      _storeCacheClear(kc);
      const cv=await storeGet(kc);
      if(cv){ const co=JSON.parse(cv)||{}; Object.assign(doServidor, co.fotos||{}); }
      else leituraCompleta=false;
    }catch(e){ leituraCompleta=false; }
  }
  if(leituraCompleta){ for(const f in doServidor){ if(!mapa[f]) mapa[f]=doServidor[f]; } }
  // monta os pedaços por tamanho
  const chunks=[]; let atual={}, tam=0;
  for(const fid in mapa){
    const b=mapa[fid]; const add=fid.length+b.length+8;
    if(tam>0 && tam+add>_REL_CHUNK_MAX){ chunks.push(atual); atual={}; tam=0; }
    atual[fid]=b; tam+=add;
  }
  if(Object.keys(atual).length) chunks.push(atual);
  // sem leitura completa: só ACRESCENTA pedaços depois dos antigos (nada é sobrescrito)
  const inicio = leituraCompleta ? 0 : antigos;
  let totalBytes=0;
  for(let i2=0;i2<chunks.length;i2++){
    const payload=JSON.stringify({fotos:chunks[i2]}); totalBytes+=payload.length;
    let ok=await storeSet(kmeta+":c"+(inicio+i2), payload);
    if(!ok){ await new Promise(res=>setTimeout(res,900)); ok=await storeSet(kmeta+":c"+(inicio+i2), payload); }
    if(!ok) return false; // um pedaço falhou — o meta antigo continua válido
  }
  let okMeta=await storeSet(kmeta, JSON.stringify({chunks:inicio+chunks.length}));
  if(!okMeta){ await new Promise(res=>setTimeout(res,900)); okMeta=await storeSet(kmeta, JSON.stringify({chunks:inicio+chunks.length})); }
  if(!okMeta) return false;
  // apagar sobras SÓ quando a leitura foi completa (compactação segura)
  if(leituraCompleta){ for(let i2=inicio+chunks.length;i2<antigos;i2++){ try{ await storeDel(kmeta+":c"+i2); }catch(e){} } }
  r.fotosBytes=totalBytes; // aproximado, usado no medidor de espaço
  return true;
}

// lê as fotos do relatório (formato novo em pedaços OU formato antigo de chave única)
async function _relLerFotos(id, forcar){
  const kmeta="mafra:relfotos:"+id;
  if(forcar) _storeCacheClear(kmeta);
  let meta=null;
  try{ const v=await storeGet(kmeta); if(v) meta=JSON.parse(v)||null; }catch(e){}
  if(!meta) return null;
  if(meta.fotos) return meta.fotos; // formato antigo (tudo numa chave)
  if(meta.chunks){
    const mapa={};
    for(let i=0;i<meta.chunks;i++){
      const kc=kmeta+":c"+i; if(forcar) _storeCacheClear(kc);
      try{ const cv=await storeGet(kc); if(cv){ const co=JSON.parse(cv)||{}; Object.assign(mapa, co.fotos||{}); } }catch(e){}
    }
    return Object.keys(mapa).length?mapa:null;
  }
  return null;
}

// apaga TODAS as chaves de fotos do relatório (meta + pedaços)
async function _relApagarFotos(id){
  const kmeta="mafra:relfotos:"+id;
  let n=0;
  try{ const v=await storeGet(kmeta); if(v){ const o=JSON.parse(v)||{}; if(o.chunks) n=o.chunks; } }catch(e){}
  for(let i=0;i<n+6;i++){ try{ await storeDel(kmeta+":c"+i); }catch(e){} } // +6 defensivo (se a contagem mudou)
  try{ await storeDel(kmeta); }catch(e){}
}

// 🔒 build 122: em vez de apagar, MOVE as fotos para a lixeira do servidor
// (mafra:lixeira:relfotos:<id>). Só apaga o original depois que a cópia gravou.
async function _relMoverFotosLixeira(id){
  const kmeta="mafra:relfotos:"+id, klix="mafra:lixeira:relfotos:"+id;
  let n=0;
  try{ const v=await storeGet(kmeta); if(v){ const o=JSON.parse(v)||{}; if(o.chunks) n=o.chunks; } }catch(e){}
  const mover=async(orig,dest)=>{ try{ const v=await storeGet(orig); if(v){ const ok=await storeSet(dest,v); if(ok) await storeDel(orig); } }catch(e){} };
  for(let i=0;i<n+6;i++){ await mover(kmeta+":c"+i, klix+":c"+i); }
  await mover(kmeta, klix);
}

// ♻️ build 122 — RESGATE LOCAL AUTOMÁTICO
// Cada aparelho guarda cópia local (navegador) de tudo que já leu/gravou.
// Ao abrir o app, este vigia confere se o servidor está com fotos faltando
// e DEVOLVE as cópias que este aparelho ainda tiver. Regras: só acrescenta
// (nunca apaga, nunca substitui por menos) e roda 1x por sessão.
let _relResgateLocalRodou=false;
async function _relResgateLocal(){
  if(_relResgateLocalRodou || !SB) return;
  _relResgateLocalRodou=true;
  try{
    const d=await loadRelatorios(true);
    const rels=(d.list||[]).filter(r=>r&&r.id&&!r.arquivado);
    if(!rels.length) return;
    // chaves de fotos que EXISTEM no servidor (só os nomes — leve)
    let noServidor=new Set();
    try{
      const {data,error}=await SB.from("dados").select("chave").like("chave","mafra:relfotos:%");
      if(error) return; (data||[]).forEach(x=>noServidor.add(x.chave));
    }catch(e){ return; }
    let fotosDevolvidas=0, relsAjudados=0;
    for(const r of rels){
      const kmeta="mafra:relfotos:"+r.id;
      let devolveuAqui=false;
      // 1) relatório SEM meta no servidor, mas com cópia local completa ou parcial
      if(!noServidor.has(kmeta)){
        const vloc=lsGet(kmeta); if(!vloc) continue;
        let nloc=0; try{ const o=JSON.parse(vloc)||{}; nloc=o.chunks||0; }catch(e){ continue; }
        let maior=-1;
        for(let i=0;i<nloc+6;i++){
          const cv=lsGet(kmeta+":c"+i);
          if(cv){ const ok=await storeSet(kmeta+":c"+i, cv); if(ok){ maior=Math.max(maior,i);
            try{ fotosDevolvidas+=Object.keys((JSON.parse(cv)||{}).fotos||{}).length; }catch(e){} devolveuAqui=true; } }
        }
        if(maior>=0){ await storeSet(kmeta, JSON.stringify({chunks:maior+1})); }
      } else {
        // 2) meta existe: repõe pedaços que faltam e COMPLETA pedaços que perderam fotos
        let nsrv=0; try{ const v=await storeGet(kmeta); const o=v?JSON.parse(v):null; nsrv=(o&&o.chunks)||0; }catch(e){}
        for(let i=0;i<nsrv+6;i++){
          const kc=kmeta+":c"+i; const cloc=lsGet(kc); if(!cloc) continue;
          let fl={}; try{ fl=(JSON.parse(cloc)||{}).fotos||{}; }catch(e){ continue; }
          if(!Object.keys(fl).length) continue;
          if(!noServidor.has(kc)){
            const ok=await storeSet(kc, cloc);
            if(ok){ fotosDevolvidas+=Object.keys(fl).length; devolveuAqui=true; if(i>=nsrv){ nsrv=i+1; await storeSet(kmeta, JSON.stringify({chunks:nsrv})); } }
          } else {
            let fs={}; try{ _storeCacheClear(kc); const cv=await storeGet(kc); fs=cv?((JSON.parse(cv)||{}).fotos||{}):{}; }catch(e){ continue; }
            const faltantes=Object.keys(fl).filter(f=>!fs[f]);
            if(faltantes.length){
              const unido=Object.assign({}, fl, fs); // servidor vence em empate; local só ACRESCENTA
              const ok=await storeSet(kc, JSON.stringify({fotos:unido}));
              if(ok){ fotosDevolvidas+=faltantes.length; devolveuAqui=true; }
            }
          }
        }
      }
      if(devolveuAqui) relsAjudados++;
      await new Promise(res=>setTimeout(res,150));
    }
    if(fotosDevolvidas>0){
      console.log("[resgate local] este aparelho devolveu "+fotosDevolvidas+" foto(s) de "+relsAjudados+" relatório(s) ao servidor.");
      try{ alert("♻️ Boa notícia: este aparelho tinha cópias locais de fotos que faltavam no servidor.\n\n"+fotosDevolvidas+" foto(s) de "+relsAjudados+" relatório(s) foram devolvidas agora."); }catch(e){}
    }
  }catch(e){ console.warn("[resgate local]", e); }
}

// tira os base64 do objeto (as fotos ficam só na chave própria); mantém descrições/ordem/fid
function _relStripFotos(r){
  let tirou=false;
  for(const s of ["registros","reunioes"]){
    for(const e of (r[s]||[])){
      if(_fotoEmbutida(e)){ e.foto=""; tirou=true; }
      if(_fotoDepEmbutida(e)){ e.fotoDepois=""; tirou=true; }
      if(Array.isArray(e.fotosExtras)){ for(const ex of e.fotosExtras){ if(ex && ex.foto && String(ex.foto).indexOf("data:")===0){ ex.foto=""; tirou=true; } } }
    }
  }
  if(tirou || (r.registros||[]).concat(r.reunioes||[]).some(e=>e&&(e.fid||e.fidDepois))) r.fotosSeparadas=true;
  return r;
}

// devolve uma CÓPIA do relatório com as fotos rehidratadas a partir da chave própria
async function carregarFotosRel(rel){
  const r=JSON.parse(JSON.stringify(rel||{}));
  if(!r.fotosSeparadas) return {r, ok:true};
  let mapa=await _relLerFotos(r.id, false);
  if(!mapa) mapa=await _relLerFotos(r.id, true); // última tentativa direto do servidor (ignora cache)
  if(!mapa) return {r, ok:false};
  for(const s of ["registros","reunioes"]){
    for(const e of (r[s]||[])){
      if(e && e.fid && !e.arquivada && mapa[e.fid]) e.foto=mapa[e.fid];
      if(e && e.fidDepois && !e.arquivada && mapa[e.fidDepois]) e.fotoDepois=mapa[e.fidDepois];
      if(e && !e.arquivada && Array.isArray(e.fotosExtras)){ for(const ex of e.fotosExtras){ if(ex && ex.fid && mapa[ex.fid]) ex.foto=mapa[ex.fid]; } }
    }
  }
  return {r, ok:true};
}

// grava o índice; se ainda houver relatórios antigos com fotos embutidas,
// separa as fotos primeiro (migração automática) para o índice ficar leve
let _relMigrando=false;
async function salvarIndiceRelatorios(d, opts){
  opts=opts||{};
  const pendentes=(d.list||[]).filter(_relTemFotoEmbutida);
  if(pendentes.length){
    let i=0;
    for(const r of pendentes){
      i++;
      mostrarCarregandoRel(`Otimizando armazenamento (${i}/${pendentes.length})…`);
      const ok=await _relGravarFotosDe(r);
      if(!ok) break; // sem rede: tenta gravar o índice mesmo assim abaixo
      _relStripFotos(r);
    }
  }
  if(pendentes.length){
    // a migração em lote acima mexeu nesses relatórios (fotos → chave própria);
    // declara os ids pra mescla de segurança não descartar o trabalho dela
    opts=Object.assign({}, opts, {ids:(opts.ids||[]).concat(pendentes.map(r=>r.id||((r.condominio||"?")+"|"+(r.mesRef||"?"))))});
  }
  return await saveRelatorios(d, opts);
}

// migração em segundo plano (liderança/Julia/Bianca): um relatório por vez, sem travar a tela
async function _relMigrarFundo(){
  if(_relMigrando) return;
  const podem=(state.user && state.user.tipo==="master") || state.userId==="julia" || state.userId==="bianca";
  if(!podem) return;
  _relMigrando=true;
  try{
    let feitos=0;
    for(let volta=0; volta<200; volta++){
      // 🔒 build 122: relê a lista FRESCA a cada passo — a cópia antiga nunca
      // fica minutos na mão (era isso que atropelava status alterados por
      // outras pessoas durante a espera entre um relatório e outro)
      const d=await loadRelatorios(true);
      const r=(d.list||[]).find(_relTemFotoEmbutida);
      if(!r) break;
      if(volta===0) console.log("[relatórios] migrando fotos para chaves separadas…");
      const ok=await _relGravarFotosDe(r);
      if(!ok){ console.warn("[relatórios] migração pausada (falha ao gravar fotos de "+r.id+")"); return; }
      _relStripFotos(r);
      const okIdx=await saveRelatorios(d, {ids:[r.id||((r.condominio||"?")+"|"+(r.mesRef||"?"))]});
      if(okIdx){ feitos++; console.log("[relatórios] "+r.condominio+" · "+r.mesRef+" migrado."); }
      await new Promise(res=>setTimeout(res,400));
    }
    if(feitos) console.log("[relatórios] migração concluída — índice leve.");
  }catch(e){ console.warn("[relatórios] migração:", e); }
  finally{ _relMigrando=false; }
}

/* ============================================================
   🩺 SAÚDE DO SISTEMA — o app confere a si mesmo
   Problema que isto resolve: erro silencioso só descoberto semanas
   depois, quando já se mexeu em muita coisa. Três vigias automáticos:
   1) AUTOTESTE diário: funções críticas, gravação no servidor,
      índice de relatórios e chaves de fotos.
   2) SENTINELA de contagens: se relatórios/atendimentos/gravações
      CAÍREM de um dia para o outro sem ação legítima → avisa a Bianca.
   3) FOTOGRAFIA diária do índice de relatórios (7 dias) com restauração.
   Roda sozinho 1x ao dia no login da liderança/Julia; também sob demanda
   na aba Gerenciar → "Saúde do sistema".
   ============================================================ */
const _AUTO_FNS=["storeGet","storeSet","storeDel","loadRelatorios","saveRelatorios","salvarIndiceRelatorios","carregarFotosRel","_relGravarFotosDe","_relStripFotos","_relMigrarFundo","abrirEditorRelatorio","renderEditorRelatorio","coletarRelEdit","salvarRelatorio","visualizarRelatorioPDF","renderRelatorios","enviarRelatorioJulia","aprovarRelatorio","reprovarRelatorio","publicarRelatorio","arquivarRelatorio","excluirRelatorio","verHistoricoRelatorio","statusRelLabel","statusRelCls","_grupoStatusRel","loadCapaDe","subirCapa","subirCapaGerenciar","carregarCapasGerenciar","abrirGerenciarCapas","previewCapa","renderDashboardRelatorios","abrirListaStatus","abrirRelatorioDaNotif","addFotosRel","removerFotoRel","moverFotoRel","ordenarFotosRel","renderFotosEditor","mostrarCarregandoRel","esconderCarregandoRel","pushAviso","gerarBackup","listarChavesBackup","render","setTab","closeModal","renderProcedimentos","abrirProcedimento","voltarProcedimentos","loadProc","saveProc","abrirEditorProc","fecharEditorProc","salvarProcEditor","setFotoProc","rmFotoProc","addFotosProc","_procChecklistPDF","renderChecklists","abrirChecklists","voltarChecklists","abrirEditorCL","fecharEditorCL","salvarCL","imprimirCL","novoCL","excluirCL","novaConferencia","abrirConferencia","salvarConferencia","fecharConferencia","imprimirConferencia","_clSetSt","_clFase","_clConfItem","_clToggleModelos"];

function _autoHoje(){ const d=new Date(); return d.getFullYear()+"-"+("0"+(d.getMonth()+1)).slice(-2)+"-"+("0"+d.getDate()).slice(-2); }

// executa todas as verificações; devolve {ts, falhas, avisos, itens:[{nome,ok,nivel,detalhe}]}
async function executarAutoteste(){
  const itens=[];
  const add=(nome,ok,detalhe,nivel)=>itens.push({nome, ok:!!ok, nivel:ok?"ok":(nivel||"falha"), detalhe:detalhe||""});

  // 1) versão e funções críticas
  add("Versão do app", typeof APP_VERSAO==="string"&&!!APP_VERSAO, typeof APP_VERSAO==="string"?APP_VERSAO:"APP_VERSAO ausente");
  const faltando=_AUTO_FNS.filter(f=>{ try{ return typeof window[f]!=="function"; }catch(e){ return true; } });
  add("Funções críticas ("+_AUTO_FNS.length+")", faltando.length===0, faltando.length?("faltando: "+faltando.join(", ")):"todas presentes");

  // 2) gravação no servidor (escreve, lê e apaga uma chave de teste)
  try{
    const ping="ping-"+Date.now();
    const okW=await storeSet("mafra:autoteste:ping", ping);
    _storeCacheClear("mafra:autoteste:ping");
    const lido=await storeGet("mafra:autoteste:ping");
    await storeDel("mafra:autoteste:ping");
    add("Gravação no servidor", okW && lido===ping, okW?(lido===ping?"gravou e leu de volta":"leu valor diferente"):"falha ao gravar");
  }catch(e){ add("Gravação no servidor", false, e.message||"erro"); }

  // 3) índice de relatórios: íntegro, leve e com as chaves de fotos no lugar
  let d=null;
  try{
    _storeCacheClear("mafra:relatorios");
    d=await loadRelatorios();
    const lista=(d&&Array.isArray(d.list))?d.list:null;
    add("Índice de relatórios", !!lista, lista?(lista.length+" relatório(s)"):"formato inesperado");
    if(lista){
      const pesados=lista.filter(_relTemFotoEmbutida).length;
      add("Índice leve (fotos separadas)", pesados===0, pesados?("migração pendente em "+pesados+" relatório(s) — conclui sozinha"):"sem fotos embutidas", "aviso");
      // confere a EXISTÊNCIA das chaves de fotos dos 5 mais recentes (sem baixar as fotos)
      const recentes=lista.filter(r=>r.fotosSeparadas&&!r.arquivado).slice(-5);
      if(recentes.length && typeof SB!=="undefined" && SB){
        try{
          const chaves=recentes.map(r=>"mafra:relfotos:"+r.id);
          const {data,error}=await SB.from("dados").select("chave").in("chave",chaves);
          if(error){ add("Chaves de fotos no servidor", true, "não verificado ("+error.message+")", "aviso"); }
          else{
            const tem=new Set((data||[]).map(x=>x.chave));
            const faltam=recentes.filter(r=>!tem.has("mafra:relfotos:"+r.id));
            add("Chaves de fotos no servidor", faltam.length===0, faltam.length?("FALTAM fotos de: "+faltam.map(r=>r.condominio+" "+mesRefLabel(r.mesRef)).join(", ")):recentes.length+" conferidas");
          }
        }catch(e){ add("Chaves de fotos no servidor", true, "não verificado offline", "aviso"); }
      } else add("Chaves de fotos no servidor", true, recentes.length?"sem conexão — não verificado":"nenhum relatório com fotos separadas ainda", "aviso");
    }
  }catch(e){ add("Índice de relatórios", false, e.message||"erro"); }

  // 4) sentinela de contagens: queda brusca de um dia para o outro = alerta
  try{
    const cont={ relatorios:(d&&d.list||[]).filter(r=>!r.arquivado).length, arquivados:(d&&d.list||[]).filter(r=>r.arquivado).length };
    try{ const a=await loadAtend(); cont.atendimentos=(a.registros||[]).length; }catch(e){}
    try{ const g=await loadGravacoes(); cont.gravacoes=((g&&g.list)||[]).length; }catch(e){}
    try{ const c=await loadChamados(); cont.chamados=((c&&c.list)||c&&c.registros||[]).length; }catch(e){}
    let hist={};
    try{ const v=await storeGet("mafra:sentinela"); if(v) hist=JSON.parse(v)||{}; }catch(e){}
    const hoje=_autoHoje();
    const dias=Object.keys(hist).filter(k=>k!==hoje).sort();
    const ontem=dias.length?hist[dias[dias.length-1]]:null;
    const quedas=[];
    if(ontem){
      for(const k of Object.keys(cont)){
        if(k==="arquivados") continue; // arquivar é ação legítima de redução
        const antes=ontem[k]||0, agora=cont[k]||0;
        if(antes>=5 && agora < antes - Math.max(3, Math.ceil(antes*0.3))) quedas.push(`${k}: ${antes} → ${agora}`);
      }
    }
    hist[hoje]=cont;
    const chavesH=Object.keys(hist).sort(); while(chavesH.length>14){ delete hist[chavesH.shift()]; }
    await storeSet("mafra:sentinela", JSON.stringify(hist));
    add("Sentinela de dados", quedas.length===0, quedas.length?("QUEDA suspeita desde ontem — "+quedas.join(" · ")):"contagens estáveis ("+Object.entries(cont).map(([k,v])=>k+" "+v).join(" · ")+")");
  }catch(e){ add("Sentinela de dados", true, "não verificado: "+(e.message||"erro"), "aviso"); }

  // 5) fotografia diária do índice (guarda 7 dias para restauração)
  try{
    if(d && Array.isArray(d.list)){
      const hoje=_autoHoje();
      const jaTem=await storeGet("mafra:snapshot:relatorios:"+hoje);
      if(!jaTem) await storeSet("mafra:snapshot:relatorios:"+hoje, JSON.stringify(d));
      let idx={};
      try{ const v=await storeGet("mafra:snapshot:idx"); if(v) idx=JSON.parse(v)||{}; }catch(e){}
      idx[hoje]={n:(d.list||[]).length, ts:Date.now()};
      const ds=Object.keys(idx).sort();
      while(ds.length>7){ const old=ds.shift(); delete idx[old]; try{ await storeDel("mafra:snapshot:relatorios:"+old); }catch(e){} }
      await storeSet("mafra:snapshot:idx", JSON.stringify(idx));
      add("Fotografia diária do índice", true, "guardadas: "+Object.keys(idx).sort().join(", "));
    }
  }catch(e){ add("Fotografia diária do índice", true, "não gravada: "+(e.message||"erro"), "aviso"); }

  const falhas=itens.filter(i=>!i.ok&&i.nivel==="falha").length;
  const avisos=itens.filter(i=>!i.ok&&i.nivel==="aviso").length + itens.filter(i=>i.ok&&i.nivel==="aviso").length;
  const res={ts:Date.now(), por:state.userId||"", versao:(typeof APP_VERSAO==="string"?APP_VERSAO:""), falhas, avisos, itens};
  try{ await storeSet("mafra:autoteste", JSON.stringify(res)); }catch(e){}
  // falhou? avisa SOMENTE a Bianca (sino dela), não importa quem rodou a verificação
  if(falhas>0){
    const probs=itens.filter(i=>!i.ok&&i.nivel==="falha").map(i=>i.nome).join(", ");
    try{ await pushAviso("bianca",{ id:"auto"+Date.now(), texto:"🩺 Verificação encontrou problema(s)", sub:probs.slice(0,90), ts:Date.now() }); }catch(e){}
  }
  return res;
}

// roda sozinho 1x ao dia, em segundo plano, para liderança/Julia/Bianca
let _autoRodando=false;
async function agendarAutoteste(){
  if(_autoRodando) return;
  const pode=(state.user && state.user.tipo==="master") || state.userId==="julia" || state.userId==="bianca";
  if(!pode) return;
  try{
    const v=await storeGet("mafra:autoteste");
    if(v){ const ult=JSON.parse(v)||{}; if(ult.ts && (Date.now()-ult.ts) < 20*3600000) return; } // já rodou hoje
  }catch(e){}
  _autoRodando=true;
  try{ await executarAutoteste(); }catch(e){ console.warn("autoteste:", e); }
  finally{ _autoRodando=false; }
}

// restaura o índice de relatórios a partir da fotografia de um dia (só liderança/Julia)
async function restaurarSnapshotRel(dia){
  if(state.userId!=="bianca"){ alert("Apenas a Bianca pode restaurar a lista de relatórios."); return; }
  const v=await storeGet("mafra:snapshot:relatorios:"+dia);
  if(!v){ alert("Fotografia de "+dia+" não encontrada."); return; }
  let snap=null; try{ snap=JSON.parse(v); }catch(e){}
  if(!snap || !Array.isArray(snap.list)){ alert("Fotografia inválida."); return; }
  if(!confirm(`Restaurar a LISTA de relatórios como estava em ${dia} (${snap.list.length} relatório(s))?\n\nAs fotos não são afetadas — elas ficam em chaves separadas.\nO estado ATUAL será substituído.`)) return;
  if(!confirm("Confirmação final: substituir a lista atual pela de "+dia+"?")) return;
  mostrarCarregandoRel("Restaurando índice de "+dia+"…");
  let ok=false;
  try{ ok=await saveRelatorios(snap, {substituirTudo:true}); } finally { esconderCarregandoRel(); }
  if(!ok) return;
  alert("✅ Lista de relatórios restaurada para o estado de "+dia+".");
  if(state.tab==="relatorios") render(); else if(state.tab==="gerenciar") renderGerenciar();
}

// 🔒 CINTO DE SEGURANÇA (build 122)
// Problema que isto resolve: o app lia a lista, demorava subindo fotos e
// gravava a lista velha por cima — derrubando relatórios salvos por outras
// pessoas nesse meio-tempo (quedas de 31/08 a 03/09). Agora, na hora de
// gravar, a lista fresca é relida do servidor e MESCLADA: a gravação só
// toca os relatórios desta ação (ids) e só remove o que for pedido (removidos).
function _relMesclarListas(doServidor, daMemoria, idsMexidos, idsRemovidos){
  // identidade do relatório: id — ou, na falta dele, condomínio+mês (nada é ignorado)
  const chave=r=>r?(r.id||((r.condominio||"?")+"|"+(r.mesRef||"?"))):null;
  const mex=new Set(idsMexidos||[]), rem=new Set(idsRemovidos||[]);
  const porChaveLocal={}; (daMemoria||[]).forEach(r=>{ const k=chave(r); if(k) porChaveLocal[k]=r; });
  const saida=[]; const vistos=new Set();
  for(const r of (doServidor||[])){
    const k=chave(r); if(!k||rem.has(k)||rem.has(r.id)) continue;
    saida.push(((mex.has(k)||mex.has(r.id))&&porChaveLocal[k])?porChaveLocal[k]:r);
    vistos.add(k);
  }
  for(const r of (daMemoria||[])){
    const k=chave(r); if(!k||vistos.has(k)||rem.has(k)||rem.has(r.id)) continue;
    if(mex.size===0||mex.has(k)||mex.has(r.id)) saida.push(r); // relatório novo criado nesta ação
  }
  return saida;
}
async function saveRelatorios(d, opts){
  opts=opts||{};
  if(!opts.substituirTudo){
    try{
      _storeCacheClear("mafra:relatorios");
      const cru=await storeGet("mafra:relatorios");
      const fresco=cru?JSON.parse(cru):null;
      if(fresco && Array.isArray(fresco.list)){
        d=Object.assign({}, fresco, {list:_relMesclarListas(fresco.list,(d&&d.list)||[],opts.ids||[],opts.removidos||[])});
      }
    }catch(e){ console.warn("[relatórios] mescla de segurança indisponível:", e); }
  }
  let ok=await storeSet("mafra:relatorios",JSON.stringify(d));
  if(!ok){
    // tenta mais uma vez (oscilação de rede é comum no celular)
    await new Promise(res=>setTimeout(res,1200));
    ok=await storeSet("mafra:relatorios",JSON.stringify(d));
  }
  if(!ok) alert("⚠️ Não foi possível salvar no servidor.\n\nVerifique sua internet e tente novamente — as alterações desta ação NÃO foram gravadas.");
  return ok;
}

async function loadFichaCond(){
  try{ const v=await storeGet("mafra:fichas_cond"); if(v) return JSON.parse(v); }catch(e){}
  return {};
}

async function saveFichaCond(d){ return await storeSet("mafra:fichas_cond",JSON.stringify(d)); }

async function loadCapas(){
  let salvas={};
  try{ const v=await storeGet("mafra:capas_cond"); if(v) salvas=JSON.parse(v); }catch(e){}
  const toAbs = (u) => {
    if(!u) return u;
    if(u.startsWith("data:")||u.startsWith("http://")||u.startsWith("https://")) return u;
    try{ return new URL(u, window.location.href).href; }catch(e){ return u; }
  };
  const out={};
  const cc = toAbs((typeof CONTRACAPA_PADRAO==="string") ? CONTRACAPA_PADRAO : "");
  if(typeof CAPAS_EMBUTIDAS==="object"){ for(const c in CAPAS_EMBUTIDAS){ out[c]={capa:toAbs(CAPAS_EMBUTIDAS[c]), contracapa:cc}; } }
  for(const c in salvas){
    const s=salvas[c]||{};
    out[c]=Object.assign({}, out[c], {capa:toAbs(s.capa)||(out[c]&&out[c].capa), contracapa:toAbs(s.contracapa)||(out[c]&&out[c].contracapa)});
  }
  for(const c in out){ if(!out[c].contracapa) out[c].contracapa=cc; }
  return out;
}

// Capa/contracapa de UM condomínio, com 3 níveis de fonte (do mais novo ao mais antigo):
// 1) chave individual "mafra:capa:<cond>" (novo formato — leve, salva com confirmação)
// 2) blocão antigo "mafra:capas_cond" (formato legado — todos juntos numa chave só)
// 3) capas embutidas no app (CAPAS_EMBUTIDAS / CONTRACAPA_PADRAO)
async function loadCapaDe(cond){
  const toAbs = (u) => {
    if(!u) return u;
    if(u.startsWith("data:")||u.startsWith("http://")||u.startsWith("https://")) return u;
    try{ return new URL(u, window.location.href).href; }catch(e){ return u; }
  };
  let capa="", contracapa="", mesPos=null;
  // 1) chave individual (novo formato)
  try{
    const v=await storeGet("mafra:capa:"+cond);
    if(v){ const o=JSON.parse(v)||{}; capa=o.capa||""; contracapa=o.contracapa||""; if(typeof o.mesPos==="number") mesPos=o.mesPos; }
  }catch(e){}
  // 2) blocão legado (completa o que faltar)
  if(!capa || !contracapa){
    try{
      const v=await storeGet("mafra:capas_cond");
      if(v){ const all=JSON.parse(v)||{}; const s=all[cond]||{};
        if(!capa) capa=s.capa||"";
        if(!contracapa) contracapa=s.contracapa||"";
      }
    }catch(e){}
  }
  // 3) embutidas no app (sempre funcionam, mesmo offline)
  if(!capa && typeof CAPAS_EMBUTIDAS==="object" && CAPAS_EMBUTIDAS[cond]) capa=CAPAS_EMBUTIDAS[cond];
  if(!contracapa && typeof CONTRACAPA_PADRAO==="string") contracapa=CONTRACAPA_PADRAO;
  return {capa:toAbs(capa), contracapa:toAbs(contracapa), mesPos:(typeof mesPos==="number"?mesPos:23)};
}

// Migra as capas do blocão antigo para chaves individuais (1 por condomínio).
// Roda em segundo plano quando a tela de capas é aberta; só copia o que ainda não existe.
async function migrarCapasLegado(){
  try{
    const v=await storeGet("mafra:capas_cond");
    if(!v) return;
    const all=JSON.parse(v)||{};
    for(const cond of Object.keys(all)){
      const s=all[cond]||{};
      if(!s.capa && !s.contracapa) continue;
      try{
        const ja=await storeGet("mafra:capa:"+cond);
        if(ja) continue; // já migrada
        await storeSet("mafra:capa:"+cond, JSON.stringify({capa:s.capa||"", contracapa:s.contracapa||""}));
      }catch(e){}
    }
  }catch(e){}
}

function verificarImagem(url, timeoutMs){
  return new Promise(resolve=>{
    if(!url){ resolve(""); return; }
    if(url.startsWith("data:")){ resolve(url); return; } // base64 sempre vale
    const img=new Image();
    let done=false;
    const finalizar=(ok)=>{ if(done)return; done=true; resolve(ok?url:""); };
    img.onload=()=>finalizar(true);
    img.onerror=()=>finalizar(false);
    setTimeout(()=>finalizar(false), timeoutMs||4000);
    img.src=url;
  });
}

async function capasResolvidas(condominio){
  const cap=await loadCapaDe(condominio);
  const [capaOk, contraOk] = await Promise.all([verificarImagem(cap.capa), verificarImagem(cap.contracapa)]);
  return {capa: capaOk, contracapa: contraOk, mesPos: cap.mesPos};
}

async function sindicoDoCondominio(cond){
  for(const sid of SINDICOS){
    try{
      const cfg=await loadCondominios(sid);
      if((cfg.itens||[]).some(c=>(c.nome||c)===cond || c===cond)) return sid;
    }catch(e){}
  }
  return null;
}

function comprimirImagem(file, maxLado, q){
  return new Promise((resolve,reject)=>{
    const fr=new FileReader();
    fr.onload=()=>{
      const img=new Image();
      img.onload=()=>{
        let {width:w,height:h}=img;
        const m=maxLado||1200;
        // mantém proporção (nunca distorce); só reduz se passar do máximo
        if(w>h && w>m){ h=Math.round(h*m/w); w=m; }
        else if(h>=w && h>m){ w=Math.round(w*m/h); h=m; }
        const cv=document.createElement("canvas"); cv.width=w; cv.height=h;
        cv.getContext("2d").drawImage(img,0,0,w,h);
        // retorna a imagem + dimensões (para saber se é vertical ou horizontal)
        resolve({ foto: cv.toDataURL("image/jpeg", q||0.72), w, h });
      };
      img.onerror=reject;
      img.src=fr.result;
    };
    fr.onerror=reject;
    fr.readAsDataURL(file);
  });
}

function mesRefLabel(mr){ const [a,m]=mr.split("-"); return MESES_EXT[parseInt(m,10)-1]+" "+a; }

function mesAnteriorRef(){ const d=new Date(); d.setDate(1); d.setMonth(d.getMonth()-1); return d.getFullYear()+"-"+("0"+(d.getMonth()+1)).slice(-2); }

function mesRefAtual(){ const d=new Date(); return d.getFullYear()+"-"+("0"+(d.getMonth()+1)).slice(-2); }

function novoRelatorioGestor(){
  // build 125: gestor de grupo (Le Monde / Trio) escolhe o subcondomínio — o relatório é um por sub
  const listaG=(typeof condsDoGestor==="function")?condsDoGestor():[];
  const cond=(listaG.length===1)?listaG[0]:(state.user.condominio||"");
  const escolhe=listaG.length>1;
  const inp='width:100%;padding:10px 12px;border:1.5px solid var(--line);border-radius:9px;font-size:14px;background:#FCFBF8';
  const opts=[];
  const dref=new Date(); dref.setDate(1);
  for(let i=0;i<6;i++){ const m=dref.getFullYear()+"-"+("0"+(dref.getMonth()+1)).slice(-2); opts.push(m); dref.setMonth(dref.getMonth()-1); }
  document.getElementById("modalMount").innerHTML=`<div class="overlay" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:440px">
    <div class="modal-head"><h3>＋ Novo relatório</h3><button class="x" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <div class="field"><label style="display:block;font-size:12px;font-weight:700;margin-bottom:5px">Condomínio</label>
        ${escolhe?`<select id="novoRelCondG" style="${inp}">${condOptionsAgrupadas(undefined,listaG)}</select>`:`<div style="${inp};background:#f3f4f6;color:#555;font-weight:600">${esc(cond||"Seu condomínio")}</div>`}</div>
      <div class="field"><label style="display:block;font-size:12px;font-weight:700;margin-bottom:5px">Mês de referência <small style="font-weight:400;text-transform:none;color:var(--muted)">— qual mês este relatório se refere</small></label>
        <select id="novoRelMes" style="${inp}">${opts.map((m,i)=>`<option value="${m}" ${i===1?"selected":""}>${mesRefLabel(m)}</option>`).join("")}</select></div>
      <div class="modal-foot" style="margin-top:14px"><button class="btn-cancel" onclick="closeModal()">Cancelar</button><button class="btn-primary" style="flex:1" onclick="const m=document.getElementById('novoRelMes').value;const sg=document.getElementById('novoRelCondG');const c=sg?sg.value:'${esc(_jsq(cond))}';closeModal();abrirEditorRelatorio(c,m);">Continuar</button></div>
    </div></div></div>`;
}

async function abrirEditorRelatorio(cond, mesRef, id){
  if(id) mostrarCarregandoRel("Abrindo o relatório…"); // ao editar, baixa a versão mais recente (pode demorar uns segundos)
  let d, rel;
  try{
    d=await loadRelatorios(!!id); // ao editar um existente, busca a versão mais recente do servidor
    rel = id ? (d.list||[]).find(r=>r.id===id) : null;
    if(rel && rel.fotosSeparadas){
      mostrarCarregandoRel("Baixando as fotos do relatório…");
      const h=await carregarFotosRel(rel);
      if(!h.ok){ esconderCarregandoRel(); alert("Não consegui baixar as fotos deste relatório agora. Verifique a conexão e tente de novo — abrir sem as fotos poderia apagá-las ao salvar."); return; }
      rel=h.r;
    }
  } finally { esconderCarregandoRel(); }
  if(id && !rel){ alert("Relatório não encontrado. Atualize a página (F5) e tente de novo."); return; }
  if(!rel){
    // tenta puxar ficha técnica fixa do condomínio
    const fichas=await loadFichaCond();
    const f=fichas[cond]||{};
    rel={ id:null, condominio:cond, mesRef:mesRef||mesAnteriorRef(), status:"rascunho",
      info:{ocupReforma:0,ocupVazia:0,ocupOcupada:0, inauguracao:f.inauguracao||"",areaConstruida:f.areaConstruida||"",areaTerreno:f.areaTerreno||"",torres:f.torres||"",unidades:f.unidades||"",vagas:f.vagas||""},
      corretivas:{eletrica:0,hidraulica:0,civil:0}, preventivas:{previstas:0,realizadas:0,emAberto:0},
      listaCorretiva:[], listaPreventiva:[], registros:[], reunioes:[],
      ordenacao:{registros:"personalizada",reunioes:"personalizada"} };
  }
  relEditState=JSON.parse(JSON.stringify(rel));
  _relMigraRegistros(relEditState);
  // normaliza relatórios antigos (criados antes da seção Reuniões / ordenação existir)
  if(!Array.isArray(relEditState.registros)) relEditState.registros=[];
  if(!Array.isArray(relEditState.reunioes)) relEditState.reunioes=[];
  if(!relEditState.ordenacao||typeof relEditState.ordenacao!=="object") relEditState.ordenacao={registros:"personalizada",reunioes:"personalizada"};
  if(!relEditState.ordenacao.registros) relEditState.ordenacao.registros="personalizada";
  if(!relEditState.ordenacao.reunioes) relEditState.ordenacao.reunioes="personalizada";
  renderEditorRelatorio();
}

