async function termometro(uid){
  const acc=USUARIOS[uid]; if(!acc){ alert("Pessoa não encontrada."); return; }
  const ehEu = (uid===state.userId);
  const tituloModal = ehEu ? "🌡️ Meu termômetro" : ("🌡️ Termômetro · "+acc.nome.split(" ")[0]);
  const wk=weekKey(state.semana);
  const ag=await loadAgenda(uid);
  const ts=(ag.weeks&&ag.weeks[wk])||[];
  // métricas locais
  const total=ts.length;
  const feitas=ts.filter(t=>t.status==="concluido").length;
  const andamento=ts.filter(t=>t.status==="em_andamento").length;
  const pend=total-feitas-andamento;
  const horas=ts.reduce((a,t)=>a+(parseFloat(t.horas)||0),0);
  // distribuição por dia
  const porDia={}; DIAS.forEach(dd=>porDia[dd.k]=0);
  ts.forEach(t=>{ if(porDia[t.dia]!==undefined) porDia[t.dia]++; });
  const maxDia=Math.max(...Object.values(porDia));
  const diaCheio=DIAS.find(dd=>porDia[dd.k]===maxDia);
  const altaPrio=ts.filter(t=>t.prioridade==="alta"&&t.status!=="concluido").length;
  // índice de carga local (0-100) — combina volume, pendências e concentração num dia
  let carga=Math.min(100, total*9 + pend*6 + altaPrio*8 + (maxDia>=4?15:maxDia>=3?8:0));
  if(total===0) carga=0;
  const nivel = carga>=70?"alta":carga>=40?"media":(total===0?"vazia":"saudavel");
  const cores={alta:"#C0392B",media:"#E08A1E",saudavel:"#2F9E44",vazia:"#8a93a5"};
  const rotulos={alta:"Carga ALTA",media:"Carga MODERADA",saudavel:"Carga saudável",vazia:"Sem tarefas"};

  // monta o modal já com o termômetro (a IA entra depois)
  const pct=Math.round(carga);
  document.getElementById("modalMount").innerHTML=`<div class="overlay" onclick="if(event.target===this)closeModal()"><div class="modal" style="max-width:480px">
    <div class="modal-head"><h3>${tituloModal}</h3><button class="x" onclick="closeModal()">×</button></div>
    <div class="modal-body">
      <div class="termo-wrap">
        <div class="termo-bar"><div class="termo-fill" style="width:${pct}%;background:${cores[nivel]}"></div></div>
        <div class="termo-lbl" style="color:${cores[nivel]}">${rotulos[nivel]} · ${pct}%</div>
      </div>
      <div class="termo-stats">
        <div><b>${total}</b><span>tarefas</span></div>
        <div><b>${feitas}</b><span>concluídas</span></div>
        <div><b>${pend}</b><span>pendentes</span></div>
        ${horas?`<div><b>${horas%1?horas.toFixed(1):horas}h</b><span>horas</span></div>`:""}
      </div>
      <div id="termoIA" class="termo-ia"><div class="termo-loading">✨ A IA está analisando a produtividade…</div></div>
    </div></div></div>`;

  // prompt para a IA
  const resumo=`Pessoa: ${acc.nome} (${acc.cargo}).
Semana atual. Total de tarefas: ${total}. Concluídas: ${feitas}. Em andamento: ${andamento}. Pendentes: ${pend}. Alta prioridade não concluída: ${altaPrio}. Horas previstas: ${horas}.
Distribuição por dia: ${DIAS.map(dd=>dd.nome+"="+porDia[dd.k]).join(", ")}. Dia mais cheio: ${diaCheio?diaCheio.nome:"-"} (${maxDia} tarefas).
Índice de carga calculado: ${pct}% (${rotulos[nivel]}).`;

  const prompt=`Você é um gestor de bem-estar e produtividade da Mafra Gestão Integrada. Analise os dados de carga de trabalho ${ehEu?"DESTA PESSOA, falando diretamente com ela em segunda pessoa (use 'você')":"desta pessoa da equipe"} e responda em PT-BR, de forma breve, calorosa e prática. NÃO use markdown nem asteriscos. Estruture exatamente assim:

DIAGNÓSTICO: (1-2 frases sobre como está a produtividade e a carga)

DISTRIBUIÇÃO: (1 frase — se algum dia está sobrecarregado, sugira redistribuir tarefas para dias mais leves; se está equilibrado, elogie)

BEM-ESTAR: (2-3 lembretes curtos e gentis de autocuidado adequados à carga — beber água, fazer pausas, respeitar o horário de almoço, não pular refeições. Se a carga estiver alta, reforce a importância de pausas; se estiver saudável, parabenize e incentive manter o ritmo)

Dados:
${resumo}`;

  try{
    const resp=await chamarIA(prompt, 600);
    const el=document.getElementById("termoIA");
    if(el) el.innerHTML=formatTermoIA(resp);
  }catch(err){
    const el=document.getElementById("termoIA");
    if(el) el.innerHTML=`<div class="termo-erro">Não consegui gerar a análise da IA agora (${esc(err.message)}). O termômetro acima é baseado nos números da semana.</div>`;
  }
}

function formatTermoIA(txt){
  // transforma as seções em blocos bonitos
  const secoes=[
    {k:"DIAGNÓSTICO",ic:"📊",cor:"#16243D"},
    {k:"DISTRIBUIÇÃO",ic:"📅",cor:"#C9A24B"},
    {k:"BEM-ESTAR",ic:"💧",cor:"#2F9E44"}
  ];
  let out="";
  secoes.forEach(s=>{
    const re=new RegExp(s.k+"\\s*:?\\s*([\\s\\S]*?)(?=(DIAGNÓSTICO|DISTRIBUIÇÃO|BEM-ESTAR)\\s*:|$)","i");
    const m=txt.match(re);
    if(m&&m[1].trim()){
      out+=`<div class="termo-sec"><div class="termo-sec-h" style="color:${s.cor}">${s.ic} ${s.k.charAt(0)+s.k.slice(1).toLowerCase()}</div><div class="termo-sec-b">${esc(m[1].trim()).replace(/\n/g,"<br>")}</div></div>`;
    }
  });
  return out || `<div class="termo-sec-b">${esc(txt).replace(/\n/g,"<br>")}</div>`;
}

function ymd(d){ return d.getFullYear()+"-"+("0"+(d.getMonth()+1)).slice(-2)+"-"+("0"+d.getDate()).slice(-2); }

function toMin(hhmm){ const [h,m]=hhmm.split(":").map(Number); return h*60+m; }

function toHHMM(min){ return ("0"+Math.floor(min/60)).slice(-2)+":"+("0"+(min%60)).slice(-2); }

function genSlotStarts(){ const a=[]; for(let m=EXPEDIENTE.ini*60; m+EXPEDIENTE.slot<=EXPEDIENTE.fim*60; m+=EXPEDIENTE.slot) a.push(m); return a; }

function freeSlotsFromData(events,dateStr){
  // feriado bloqueia a agenda
  const fer=feriadoStatus(dateStr);
  if(fer && fer.bloqueio==="total") return [];
  const busy=(events||[]).filter(e=>e.date===dateStr).map(e=>[toMin(e.start),toMin(e.end)]);
  const now=new Date(); const todayStr=ymd(now); const nowMin=now.getHours()*60+now.getMinutes();
  const meioCorte=12*60; // meio período = só de manhã (até 12h)
  return genSlotStarts().filter(s=>{
    const e=s+EXPEDIENTE.slot;
    if(fer && fer.bloqueio==="meio" && s>=meioCorte) return false; // tarde bloqueada
    if(dateStr===todayStr && s<=nowMin) return false;
    return !busy.some(([bs,be])=>s<be && e>bs);
  });
}

function gcalLink(ev){
  const s=ev.date.replace(/-/g,"")+"T"+ev.start.replace(":","")+"00";
  const e=ev.date.replace(/-/g,"")+"T"+ev.end.replace(":","")+"00";
  const params={action:"TEMPLATE",text:ev.title||"Evento Mafra",dates:s+"/"+e,details:ev.obs||"",location:ev.local||""};
  const emails=[];
  if(ev.participantes) ev.participantes.forEach(p=>{ if(p.tipo==="externo"&&p.email) emails.push(p.email); });
  if(ev.guest&&ev.guest.email) emails.push(ev.guest.email);
  if(emails.length) params.add=emails.join(",");
  return "https://calendar.google.com/calendar/render?"+new URLSearchParams(params).toString();
}

